const JOHN_SECTIONS = {};

JOHN_SECTIONS["1"] = [{"title":"Slovo se stalo tělem","range":"Jan 1,1–18","thoughts":[],"verses":[[1,"Na počátku bylo Slovo. Slovo bylo u Boha a to Slovo bylo Bůh."],[2,"Bylo na počátku u Boha."],[3,"Všechno vzniklo skrze ně a bez něho nevzniklo nic z toho, co existuje."],[4,"V něm byl život a tento život byl světlem lidí."],[5,"Světlo svítí v temnotě a temnota je nepohltila."],[6,"Od Boha byl poslán člověk jménem Jan."],[7,"Přišel jako svědek, aby vydal svědectví o tom světle a aby skrze něj všichni uvěřili."],[8,"On sám nebyl tím světlem; přišel, aby o světle vydal svědectví."],[9,"To pravé světlo, které osvěcuje každého člověka, přicházelo na svět."],[10,"Bylo na světě, svět skrze ně vznikl, ale svět ho nepoznal."],[11,"Přišel do svého vlastního, ale jeho vlastní ho nepřijali."],[12,"Těm, kteří ho přijali a věří v jeho jméno, však dal právo stát se Božími dětmi."],[13,"Ti se nenarodili z krve ani z vůle těla či člověka, ale z Boha."],[14,"A Slovo se stalo tělem a přebývalo mezi námi. Viděli jsme jeho slávu, slávu jednorozeného od Otce, plného milosti a pravdy."],[15,"Jan o něm vydával svědectví a volal: „To je ten, o němž jsem řekl: Ten, který přichází po mně, je přede mnou, protože byl dříve než já.“"],[16,"Z jeho plnosti jsme všichni přijali milost za milostí."],[17,"Zákon byl dán skrze Mojžíše, ale milost a pravda přišly skrze Ježíše Krista."],[18,"Boha nikdy nikdo neviděl. Jednorozený Syn, který je v Otcově náruči, nám ho dal poznat."]]},{"title":"Svědectví Jana Křtitele","range":"Jan 1,19–34","thoughts":[],"verses":[[19,"Toto je Janovo svědectví, když k němu Židé z Jeruzaléma poslali kněze a levity, aby se ho zeptali: „Kdo jsi?“"],[20,"Jan nic nezapíral, ale otevřeně vyznal: „Já nejsem Mesiáš.“"],[21,"Zeptali se ho: „Kdo tedy? Jsi Eliáš?“ Odpověděl: „Nejsem.“ „Jsi ten Prorok?“ Odpověděl: „Ne.“"],[22,"Řekli mu tedy: „Kdo jsi? Musíme dát odpověď těm, kteří nás poslali. Co říkáš sám o sobě?“"],[23,"Jan odpověděl: „Jsem hlas volajícího na poušti: ‚Narovnejte cestu Pánu,‘ jak řekl prorok Izajáš.“"],[24,"Ti, kdo byli posláni, patřili k farizeům."],[25,"Zeptali se ho: „Proč tedy křtíš, když nejsi Mesiáš ani Eliáš ani ten Prorok?“"],[26,"Jan jim odpověděl: „Já křtím vodou, ale mezi vámi stojí někdo, koho neznáte."],[27,"To je ten, který přichází po mně a je přede mnou. Nejsem hoden ani rozvázat řemínek jeho sandálu.“"],[28,"To se stalo v Betabaře za Jordánem, kde Jan křtil."],[29,"Druhého dne Jan uviděl Ježíše, jak k němu přichází, a řekl: „Hle, Beránek Boží, který snímá hřích světa!"],[30,"To je ten, o němž jsem řekl: ‚Za mnou přichází muž, který je přede mnou, protože byl dříve než já.‘"],[31,"Ani já jsem ho neznal. Přišel jsem však křtít vodou proto, aby byl zjeven Izraeli.“"],[32,"Jan také vydal svědectví: „Viděl jsem Ducha sestupovat z nebe jako holubici a zůstávat na něm."],[33,"Ani já jsem ho neznal, ale ten, který mě poslal křtít vodou, mi řekl: ‚Na koho uvidíš sestupovat Ducha a zůstávat na něm, to je ten, který křtí Duchem svatým.‘"],[34,"Já jsem to viděl a dosvědčuji, že on je Boží Syn.“"]]},{"title":"První učedníci","range":"Jan 1,35–42","thoughts":[],"verses":[[35,"Druhého dne tam Jan znovu stál se dvěma ze svých učedníků."],[36,"Když uviděl Ježíše, jak jde kolem, řekl: „Hle, Beránek Boží!“"],[37,"Ti dva učedníci slyšeli, co řekl, a šli za Ježíšem."],[38,"Ježíš se obrátil, uviděl je, jak jdou za ním, a zeptal se: „Co hledáte?“ Odpověděli: „Rabbi,“ což znamená Mistře, „kde bydlíš?“"],[39,"Řekl jim: „Pojďte a uvidíte.“ Šli tedy, viděli, kde bydlí, a zůstali u něj ten den. Bylo kolem desáté hodiny."],[40,"Jedním z těch dvou, kteří slyšeli Jana a šli za Ježíšem, byl Ondřej, bratr Šimona Petra."],[41,"Ten nejprve našel svého bratra Šimona a řekl mu: „Našli jsme Mesiáše,“ což znamená Kristus."],[42,"A přivedl ho k Ježíšovi. Ježíš se na něj podíval a řekl: „Ty jsi Šimon, syn Jonášův. Budeš se jmenovat Kéfas,“ což znamená Petr."]]},{"title":"Filip a Natanael","range":"Jan 1,43–51","thoughts":[],"verses":[[43,"Následujícího dne se Ježíš rozhodl odejít do Galileje. Našel Filipa a řekl mu: „Následuj mě.“"],[44,"Filip byl z Betsaidy, města Ondřejova a Petrova."],[45,"Filip našel Natanaela a řekl mu: „Našli jsme toho, o němž psal Mojžíš v Zákoně i Proroci: Ježíše, syna Josefova z Nazareta.“"],[46,"Natanael mu řekl: „Může z Nazareta vzejít něco dobrého?“ Filip odpověděl: „Pojď a podívej se.“"],[47,"Když Ježíš uviděl Natanaela, jak k němu přichází, řekl o něm: „Hle, opravdový Izraelita, v němž není lest.“"],[48,"Natanael se zeptal: „Odkud mě znáš?“ Ježíš mu odpověděl: „Ještě než tě Filip zavolal, viděl jsem tě pod fíkovníkem.“"],[49,"Natanael mu odpověděl: „Mistře, ty jsi Boží Syn, ty jsi král Izraele!“"],[50,"Ježíš mu řekl: „Věříš proto, že jsem ti řekl, že jsem tě viděl pod fíkovníkem? Uvidíš ještě větší věci.“"],[51,"A dodal: „Amen, amen, říkám vám: Uvidíte otevřené nebe a Boží anděly vystupovat a sestupovat na Syna člověka.“"]]}];

JOHN_SECTIONS["2"] = [{"title":"Svatba v Káně","range":"Jan 2,1–12","thoughts":[],"verses":[[1,"Třetího dne se konala svatba v galilejské Káně a byla tam Ježíšova matka."],[2,"Na svatbu byl pozván také Ježíš se svými učedníky."],[3,"Když došlo víno, řekla Ježíšova matka: „Nemají víno.“"],[4,"Ježíš jí odpověděl: „Ženo, co to ode mě žádáš? Moje hodina ještě nepřišla.“"],[5,"Jeho matka řekla služebníkům: „Udělejte všechno, co vám řekne.“"],[6,"Stálo tam šest kamenných nádob určených k židovskému očišťování; každá pojala dvě až tři míry."],[7,"Ježíš služebníkům řekl: „Naplňte ty nádoby vodou.“ Naplnili je až po okraj."],[8,"Potom jim řekl: „Teď naberte a doneste správci hostiny.“ A oni mu donesli."],[9,"Správce hostiny ochutnal vodu, která se proměnila ve víno. Nevěděl, odkud víno je, ale služebníci, kteří vodu nabírali, to věděli. Zavolal ženicha"],[10,"a řekl mu: „Každý podává nejprve dobré víno a teprve když se hosté napijí, přinese horší. Ty jsi však dobré víno uchoval až doteď.“"],[11,"Toto první znamení udělal Ježíš v galilejské Káně. Zjevil svou slávu a jeho učedníci v něj uvěřili."],[12,"Potom sestoupil do Kafarnaum spolu se svou matkou, bratry a učedníky. Zůstali tam několik dní."]]},{"title":"Vyčištění chrámu","range":"Jan 2,13–25","thoughts":[],"verses":[[13,"Blížily se židovské Velikonoce a Ježíš vystoupil do Jeruzaléma."],[14,"V chrámě našel prodavače volů, ovcí a holubic a také penězoměnce sedící u svých stolů."],[15,"Udělal si z provázků bič a všechny vyhnal z chrámu, ovce i dobytek. Penězoměncům rozsypal mince a převrátil jejich stoly."],[16,"Prodavačům holubic řekl: „Odneste to odsud! Nedělejte z domu mého Otce tržiště.“"],[17,"Jeho učedníci si vzpomněli, že je napsáno: „Horlivost pro tvůj dům mě stravuje.“"],[18,"Židé se ho zeptali: „Jakým znamením nám prokážeš, že smíš takto jednat?“"],[19,"Ježíš jim odpověděl: „Zbořte tento chrám a za tři dny ho znovu postavím.“"],[20,"Židé řekli: „Tento chrám se stavěl čtyřicet šest let, a ty ho chceš postavit za tři dny?“"],[21,"On však mluvil o chrámu svého těla."],[22,"Když potom vstal z mrtvých, jeho učedníci si vzpomněli, že to říkal. Uvěřili Písmu i slovu, které Ježíš řekl."],[23,"Když byl o velikonočních svátcích v Jeruzalémě, mnozí uvěřili v jeho jméno, protože viděli znamení, která dělal."],[24,"Ježíš se jim však nesvěřoval, protože všechny znal."],[25,"Nepotřeboval, aby mu někdo vydával svědectví o člověku. Sám totiž věděl, co je v člověku."]]}];

JOHN_SECTIONS["3"] = [{"title":"Ježíš a Nikodém","range":"Jan 3,1–21","thoughts":[],"verses":[[1,"Mezi farizeji byl muž jménem Nikodém, jeden z předních mužů mezi Židy."],[2,"Ten přišel k Ježíšovi v noci a řekl mu: „Mistře, víme, že jsi učitel, který přišel od Boha. Nikdo totiž nemůže dělat znamení, která děláš ty, není-li s ním Bůh.“"],[3,"Ježíš mu odpověděl: „Amen, amen, říkám ti: Kdo se nenarodí znovu, nemůže spatřit Boží království.“"],[4,"Nikodém se zeptal: „Jak se může člověk narodit, když je starý? Může snad podruhé vstoupit do života své matky a narodit se?“"],[5,"Ježíš odpověděl: „Amen, amen, říkám ti: Kdo se nenarodí z vody a z Ducha, nemůže vejít do Božího království."],[6,"Co se narodilo z těla, je tělo, a co se narodilo z Ducha, je duch."],[7,"Nediv se, že jsem ti řekl: Musíte se narodit znovu."],[8,"Vítr vane, kam chce. Slyšíš jeho hlas, ale nevíš, odkud přichází ani kam jde. Tak je to s každým, kdo se narodil z Ducha.“"],[9,"Nikodém se ho zeptal: „Jak se to může stát?“"],[10,"Ježíš mu odpověděl: „Ty jsi učitel Izraele, a nevíš to?"],[11,"Amen, amen, říkám ti: Mluvíme o tom, co víme, a svědčíme o tom, co jsme viděli, ale naše svědectví nepřijímáte."],[12,"Když jsem vám mluvil o pozemských věcech a nevěříte, jak uvěříte, budu-li vám mluvit o nebeských?"],[13,"Nikdo nevystoupil do nebe kromě toho, který z nebe sestoupil: Syna člověka, který je v nebi."],[14,"A jako Mojžíš vyzdvihl hada na poušti, tak musí být vyzdvižen Syn člověka,"],[15,"aby každý, kdo v něj věří, nezahynul, ale měl věčný život."],[16,"Bůh totiž tak miloval svět, že dal svého jednorozeného Syna, aby žádný, kdo v něj věří, nezahynul, ale měl věčný život."],[17,"Bůh neposlal svého Syna na svět proto, aby svět odsoudil, ale aby byl svět skrze něj zachráněn."],[18,"Kdo v něj věří, není odsouzen. Kdo však nevěří, už je odsouzen, protože neuvěřil ve jméno jednorozeného Božího Syna."],[19,"A soud spočívá v tom, že světlo přišlo na svět, ale lidé si zamilovali tmu víc než světlo, protože jejich skutky byly zlé."],[20,"Každý, kdo jedná zle, nenávidí světlo a nejde ke světlu, aby jeho skutky nebyly odhaleny."],[21,"Kdo však žije podle pravdy, přichází ke světlu, aby se ukázalo, že jeho skutky byly vykonány v Bohu.“"]]},{"title":"Janovo poslední svědectví","range":"Jan 3,22–36","thoughts":[],"verses":[[22,"Potom přišel Ježíš se svými učedníky do Judska. Nějaký čas tam s nimi pobýval a křtil."],[23,"Také Jan křtil v Enonu blízko Salimu, protože tam bylo mnoho vody. Lidé k němu přicházeli a dávali se křtít."],[24,"Jan tehdy ještě nebyl uvězněn."],[25,"Mezi Janovými učedníky a jedním Židem vznikl spor o očišťování."],[26,"Přišli tedy k Janovi a řekli mu: „Mistře, ten, který byl s tebou za Jordánem a o němž jsi vydal svědectví, teď sám křtí a všichni jdou k němu.“"],[27,"Jan odpověděl: „Člověk si nemůže vzít nic, pokud mu to nebylo dáno z nebe."],[28,"Vy sami jste svědky toho, že jsem řekl: ‚Já nejsem Mesiáš, ale byl jsem poslán před ním.‘"],[29,"Ženich je ten, kdo má nevěstu. Ženichův přítel stojí, naslouchá mu a raduje se z jeho hlasu. Právě proto je má radost nyní úplná."],[30,"On musí růst a já se musím zmenšovat."],[31,"Kdo přichází shůry, je nade všemi. Kdo je ze země, patří zemi a mluví o pozemských věcech. Ten, kdo přichází z nebe, je nade všemi."],[32,"Svědčí o tom, co viděl a slyšel, ale jeho svědectví téměř nikdo nepřijímá."],[33,"Kdo jeho svědectví přijímá, potvrzuje tím, že Bůh mluví pravdu."],[34,"Ten, koho Bůh poslal, mluví Boží slova, protože Bůh mu dává Ducha bez míry."],[35,"Otec miluje Syna a všechno vložil do jeho rukou."],[36,"Kdo věří v Syna, má věčný život. Kdo však Synu nevěří, život neuvidí; zůstává na něm Boží hněv."]]}];

JOHN_SECTIONS["4"] = [{"title":"Ježíš a samařská žena","range":"Jan 4,1–42","thoughts":[],"verses":[[1,"jakž poznal Pán, že slyšeli farizeové, že by Ježíš více učedníků činil a křtil než Jan,"],[2,"(Ačkoli Ježíš sám nekřtil, ale učedlníci jeho),"],[3,"Opustil Judstvo, a odšel znovu do Galilee."],[4,"Musil pak jíti skrze Samaří."],[5,"přišel k městu Samařskému, kteréž slove Sichar, vedlé popluží, kteréž byl dal Jákob Jozefovi, synu svému."],[6,"Byla pak tu studnice Jákobova. Protož ustav na cestě Ježíš, posadil se tak na studnici. A bylo okolo šesté hodiny."],[7,"přišla žena z Samaří vážiti vody. Kteréž řekl Ježíš: Dej mi píti."],[8,"Protože učedlníci jeho byli odešli do města, aby nakoupili pokrmů."],[9,"řekla mu žena ta Samaritánka: Kterakž ty, když byl Žid, žádáš ode mne nápoje od ženy Samaritánky? (Protože neobcují Židé s Samaritány.)"],[10,"Odpověděl Ježíš a řekl jí: Kdybys znala ten dar Boží, a kdo je ten, kterýž praví tobě: Dej mi píti, ty bys prosila jeho, a dal by tobě vody živé."],[11,"dí mu žena: Pane, aniž máš, čím bys navážil, a studnice je hluboká. Odkudž tedy máš tu vodu živou?"],[12,"Zdaliž jsi ty větší nežli otec náš Jákob, kterýž nám dal tuto studnici, a sám z ní pil, i synové jeho, i dobytek jeho?"],[13,"Odpověděl Ježíš a řekl jí: Každý, kdož pije vodu tuto, žízniti bude znovu."],[14,"Ale kdož by se napil vody té, kterouž já dám mu, nežíznil by na věky, ale voda ta, kterouž já dám mu, bude v něm studnicí vody prýštící se k životu věčnému."],[15,"Řekla mu žena: Pane, dej mi té vody, abych nežíznila, ani chodila sem vážiti."],[16,"Řekl jí Ježíš: Jdi, zavolej muže svého, a přiď sem."],[17,"Odpověděla žena a řekla: Nemám muže. Dí jí Ježíš: Dobřes řekla: Nemám muže."],[18,"Nebos pět mužů měla, a nyní kteréhož máš, není tvůj muž. To jsi pravdu pověděla."],[19,"Řekla mu žena: Pane, vidím, že jsi ty prorok."],[20,"Otcové naši na této hoře modlívali se, a vy říkáte, že v Jeruzalémě je místo, kdež náleží se modliti."],[21,"Dí jí Ježíš: Ženo, věř mi, žeť jde hodina, kdyžto ani na této hoře, ani v Jeruzalémě nebudete se modliti Otci."],[22,"Vy se modlíte, a nevíte, čemu; my se modlíme, čemuž víme, nebo spasení z Židů je."],[23,"Ale jdeť hodina, a nyníť je, kdyžto praví modlitebníci modliti se budou Otci v duchu a v pravdě. Protožeť takových Otec hledá, aby se modlili mu."],[24,"Bůh duch je, a ti, kteříž se mu modlí, v duchu a v pravdě musejí se modliti."],[25,"Dí mu žena: Vím, že Mesiáš přijde, kterýž slove Kristus. Ten, když přijde, oznámí nám všechno."],[26,"Dí jí Ježíš: Jáť jsem, kterýž mluvím s tebou."],[27,"v tom přišli učedlníci jeho, i divili se, že by s ženou mluvil, a však žádný neřekl: Nač se ptáš, aneb proč mluvíš s ní?"],[28,"nechala tu žena vědra svého, a šla do města, a řekla těm lidem:"],[29,"Pojďte, vizte člověka, kterýž pověděl mi všechno, což jsem koli činila. Není-li on ale Kristus?"],[30,"vyšli z města, a přišli k němu."],[31,"Mezi tím pak prosili ho učedlníci, řkouce: Mistře, pojez."],[32,"on řekl jim: Jáť mám pokrm jísti, kteréhož vy nevíte."],[33,"Učedlníci pak mluvili vespolek: Zdali mu kdo přinesl jísti?"],[34,"Dí jim Ježíš: Můjť pokrm je, abych činil vůli toho, kterýž mne poslal, a dokonal řekllo jeho."],[35,"Však vy říkáte, že ještě čtyři měsícové jsou, a žeň přijde. Hle, říkám vám: Pozdvihněte očí svých, a patřte na krajiny, žeť se již bělejí ke žni."],[36,"Kdož pak žne, odplatuť béře, a shromažďuje užitek k životu věčnému, aby i ten, kdož rozsívá, radoval se spolu, i kdo žne."],[37,"Protože v tom pravé je slovo, žeť jiný je, kdož rozsívá, a jiný, kterýž žne."],[38,"Jáť jsem vás poslal žíti, o čemž jste vy nepracovali. Jiníť pracovali, a vy jste v jejich práce vešli."],[39,"Z města pak toho mnozí z Samaritánů uvěřili v něj, pro řeč té ženy, svědčící: Že mi pověděl všechno, což jsem činila."],[40,"když k němu přišli Samaritáni, prosili ho, aby s nimi zůstal. A pobyl tu za dva dni."],[41,"mnohem jich více uvěřilo pro řeč jeho."],[42,"ženě té řekli: Již ne pro tvé vypravování věříme; nebo sami jsme slyšeli, a víme, že tento je právě spasitel světa, Kristus."]]},{"title":"Uzdravení syna královského služebníka","range":"Jan 4,43–54","thoughts":[],"verses":[[43,"Po dvou pak dnech vyšel odtud, a šel do Galilee."],[44,"Protože sám Ježíš byl svědectví vydal, že prorok v vlasti své v poctivosti není."],[45,"když přišel do Galilee, přijali ho Galilejští, všechno když vidělše, co činil v Jeruzalémě v svátek; nebo i oni byli přišli k svátku."],[46,"znovu přišel Ježíš do Kány Galilejské, kdež udělal byl z vody víno. A byl jeden královský služebník v Kafarnaum, jehožto syn nemocen byl."],[47,"Ten uslyšev, že by Ježíš přišel z Judstva do Galilee, šel k němu, a prosil ho, aby sstoupil a uzdravil syna jeho; nebo počínal umírati."],[48,"řekl mu Ježíš: Neuzříte-li divů a zázraků, neuvěříte."],[49,"Dí mu ten královský služebník: Pane, podiž prvé, nežli umře syn můj."],[50,"Dí mu Ježíš: Jdi, syn tvůj živ je. A uvěřil člověk řeči, kterouž mluvil mu Ježíš, a šel."],[51,"Když pak on již šel, potkali se s ním služebníci jeho a zvěstovali, řkouce: Syn tvůj živ je."],[52,"otázal se jich na hodinu, v kterou by se lépe měl. A řekli mu: Včera v hodinu sedmou přestala mu zimnice."],[53,"poznal otec, že právě ta hodina byla, v kterouž řekl byl mu Ježíš: Syn tvůj živ je. A uvěřil on i dům jeho celý."],[54,"To znovu druhý div udělal Ježíš, přišel z Judstva do Galilee."]]}];

JOHN_SECTIONS["5"] = [{"title":"Uzdravení u rybníka Bethesda","range":"Jan 5,1–18","thoughts":[],"verses":[[1,"byl svátek Židovský, i šel Ježíš do Jeruzaléma."],[2,"Byl pak v Jeruzalémě rybník bravný, kterýž slove Židovsky Bethesda, patero přístřeší měl."],[3,"Kdež leželo množství veliké neduživých, slepých, kulhavých, suchých, očekávajících hnutí vody."],[4,"Protože anděl jistým časem sstupoval do rybníka, a kormoutil vodu. Protož kdož nejprvé sstoupil po tom zkormoucení vody, uzdraven býval, od kterékoli nemoci trápen byl."],[5,"byl tu člověk jeden, kterýž osm a třidceti let nemocen byl."],[6,"Toho když uviděl Ježíš ležícího, a poznav, že je již dávno nemocen, dí mu: Chceš-li zdráv býti?"],[7,"Odpověděl mu ten nemocný: Pane, nemám člověka, kterýž by, když se zkormoutí voda, uvrhl mne do rybníka, ale když já jdu, jiný přede mnou sstupuje."],[8,"Dí mu Ježíš: Vstaň, vezmi lůžko své a choď."],[9,"hned zdráv je učiněn člověk ten, a vzav lůžko své, i chodil. Byla pak sobota v ten den."],[10,"řekli Židé tomu uzdravenému: Sobota je, nesluší tobě lůžko nositi."],[11,"Odpověděl jim: Ten, kterýž mne uzdravil, onť mi řekl: Vezmi lůžko své a choď."],[12,"otázali se ho: Kdo je ten člověk, kterýž tobě řekl: Vezmi lůžko své a choď?"],[13,"Ten pak uzdravený nevěděl, kdo by byl. Protože Ježíš byl poodšel od zástupu shromážděného na tom místě."],[14,"pak nalezl ho Ježíš v chrámě, a řekl mu: Hle, zdráv jsi učiněn; nikoli víc nehřeš, aťby se něco horšího nepřihodilo."],[15,"Odšel ten člověk, a pověděl Židům, že by Ježíš byl ten, kterýž ho zdravého udělal."],[16,"protož protivili se Židé Ježíšovi, a hledali ho zabiti, že to udělal v sobotu."],[17,"Ježíš pak odpověděl jim: Otec můj až dosavad dělá, i jáť dělám."],[18,"Židé ještě víc proto hledali ho zamordovati, že by netoliko rušil sobotu, ale že Otce svého řekl býti Boha, rovného se čině Bohu."]]},{"title":"Syn a Otec","range":"Jan 5,19–30","thoughts":[],"verses":[[19,"odpověděl Ježíš a řekl jim: Amen, amen říkám vám: Nemůžeť Syn sám od sebe nic činiti, jediné což vidí, an Otec činí. Protože cožkoli on činí, toť i Syn též podobně činí."],[20,"Otec zajisté miluje Syna, a ukazuje mu všechno, což sám činí; a větší nad to ukáže mu skutky, abyste vy se divili."],[21,"Protože jakož Otec křísí mrtvé a obživuje, tak i Syn, kteréž chce, obživuje."],[22,"Aniž zajisté Otec soudí koho, ale celý soud dal Synu."],[23,"Aby všichni ctili Syna, tak jakž Otce ctí. Kdo nectí Syna, nectí ani Otce, kterýž ho poslal."],[24,"Amen, amen říkám vám: Že kdož slovo mé slyší, a věří tomu, kterýž mne poslal, máť život věčný, a na soud nepřijde, ale přešelť je z smrti do života."],[25,"Amen, amen říkám vám: Že přijde hodina, a nyníť je, když mrtví uslyší hlas Syna Božího, a kteříž uslyší, živi budou."],[26,"Protože jakož Otec má život sám v sobě, tak dal i Synu, aby měl život v samém sobě."],[27,"dal mu moc i soud činiti, nebo Syn člověka je."],[28,"Nedivtež se tomu; neboť přijde hodina, v kterouž všichni, kteříž v hrobích jsou, uslyší hlas jeho."],[29,"půjdou ti, kteříž dobré věci činili, na vzkříšení života, ale ti, kteříž zlé věci činili, na vzkříšení soudu."],[30,"Nemohuť já sám od sebe nic činiti. Jakžť slyším, takť soudím, a soud můj spravedlivý je. Protože nehledám vůle své, ale vůle toho, kterýž mne poslal, Otcovy."]]},{"title":"Svědectví o Ježíšovi","range":"Jan 5,31–47","thoughts":[],"verses":[[31,"Vydám-liť já svědectví sám o sobě, svědectví mé není pravé."],[32,"Jinýť je, kterýž svědectví vydává o mně, a vím, že pravé je svědectví, kteréž vydává o mně."],[33,"Vy jste byli poslali k Janovi, a on svědectví vydal pravdě."],[34,"Ale jáť nepřijímám svědectví od člověka, než totoť říkám, abyste vy spaseni byli."],[35,"Onť byl svíce hořící a svítící, vy pak chtěli jste se na čas poradovati v světle jeho."],[36,"Ale já mám větší svědectví, než Janovo. Protože skutkové, kteréž mi dal Otec, abych je vykonal, tiť skutkové, kteréž já činím, svědčí o mně, že mne Otec poslal."],[37,"kterýž mne poslal, Otec, onť svědectví vydal o mně, jehož jste vy hlasu nikdy neslyšeli, ani tváři jeho neviděli."],[38,"slova jeho nemáte v sobě zůstávajícího. Protože kteréhož on poslal, tomu vy nevěříte."],[39,"Ptejte se na písma; nebo vy domníváte se v nich věčný život míti, a tať svědectví vydávají o mně."],[40,"Ale nechcete přijíti ke mně, abyste život měli."],[41,"Chvály od lidí nepřijímám."],[42,"Ale poznal jsem vás, že milování Božího nemáte v sobě."],[43,"Já jsem přišel ve jménu Otce svého, a nepřijímáte mne. Kdyby jiný přišel ve jménu svém, toho přijmete."],[44,"Kterak vy můžete věřiti, chvály jedni od druhých hledajíce, poněvadž chvály, kteráž je od samého Boha, nehledáte?"],[45,"Nedomnívejte se, bychť já na vás žalovati měl před Otcem. Jestiť, kdo by žaloval na vás, Mojžíš, v němž vy naději máte."],[46,"Protože kdybyste věřili Mojžíšovi, věřili byste i mně; neb on o mně psal."],[47,"Ale poněvadž jeho písmům nevěříte, i jak slovům mým uvěříte?"]]}];

JOHN_SECTIONS["6"] = [{"title":"Nasycení pěti tisíc","range":"Jan 6,1–15","thoughts":[],"verses":[[1,"odšel Ježíš za moře Galilejské neb Tiberiadské."],[2,"šel za ním zástup veliký; nebo viděli divy jeho, kteréž činil nad nemocnými."],[3,"všel na horu Ježíš, a tam seděl s učedníky svými."],[4,"Byla pak blízko velikanoc, svátek Židovský."],[5,"pozdvih očí Ježíš, a když viděl, že zástup veliký jde k němu, dí Filipovi: Kde nakoupíme chlebů, aby pojedli tito?"],[6,"(Ale to řekl, pokoušeje ho; nebo on věděl, co by měl udělat.)"],[7,"Odpověděl mu Filip: Za dvě stě peněz chlebů nepostačí jim, aby jeden každý z nich něco maličko vzal."],[8,"Dí mu jeden z učedníků jeho, Ondřej, bratr Šimona Petra:"],[9,"Jestiť mládenček jeden zde, kterýž má pět chlebů ječných a dvě rybičky. Ale coť je to mezi tak mnohé?"],[10,"řekl Ježíš: Rozkažte lidu, ať se usadí. A bylo trávy mnoho na tom místě. A posadilo se mužů v počtu okolo pěti tisíců."],[11,"Ježíš vzal ty chleby, a řeklky učiniv, rozdával učedníkům, učedlníci pak sedícím; též podobně z těch rybiček, jakž mnoho chtěli."],[12,"když byli nasyceni, řekl učedníkům svým: Zbeřte ty drobty, kteříž zůstali, ať nezhynou."],[13,"sebrali a naplnili dvanácte košů drobtů z těch pěti chlebů ječných, kteříž pozůstali po těch, kteříž jedli."],[14,"Ti pak lidé, když uvidělše ten div, kterýž udělal Ježíš, říkali: Tento je jistě prorok, kterýž měl přijíti na svět."],[15,"Ježíš věda, že by měli přijíti a chytiti ho, aby ho učinili králem, ušel na horu znovu sám jediný."]]},{"title":"Ježíš kráčí po moři","range":"Jan 6,16–21","thoughts":[],"verses":[[16,"Když pak byl večer, sstoupili učedlníci jeho k moři."],[17,"vstoupivše na lodí, plavili se přes moře do Kafarnaum. A bylo již tma, a nepřišel byl Ježíš k nim."],[18,"Moře pak dutím velikého větru zdvihalo se."],[19,"odplavivše se honů jako pětmecítma neb třidceti, uzřeli Ježíše, an chodí po moři, a přibližuje se k lodí. A báli se."],[20,"On pak řekl jim: Jáť jsem, nebojte se."],[21,"vzali ho na lodí ochotně, a hned lodí přiběhla k zemi, do kteréž se plavili."]]},{"title":"Ježíš, chléb života","range":"Jan 6,22–59","thoughts":[],"verses":[[22,"Nazejtří zástup, kterýž byl za mořem, když viděl, že jiné lodičky nebylo, než ta jedna, na kterouž byli vstoupili učedlníci jeho, a že Ježíš nebyl všel s učedníky svými na lodí, ale sami učedlníci jeho byli se plavili,"],[23,"(Jiné pak lodí byly připlouly od Tiberiady k tomu místu blízko, kdež byli jedli chléb, když řeklky udělal Pán),"],[24,"Když tedy uviděl zástup, že Ježíše tu není, ani učedníků jeho, vstoupili i oni na lodí, a přijeli do Kafarnaum, hledajíce Ježíše."],[25,"nalezše ho za mořem, řekli mu: Mistře, kdy jsi sem přišel?"],[26,"Odpověděl jim Ježíš a řekl: Amen, amen říkám vám: Hledáte mne, ne proto že jste divy viděli, ale že jste jedli chleby a nasyceni jste."],[27,"Pracujte ne o pokrm, kterýž hyne, ale o ten pokrm, kterýž zůstává k životu věčnému, kterýž Syn člověka dá vám. Protože tohoť potvrdil Bůh Otec."],[28,"řekli mu: Co budeme činiti, abychom dělali řekllo Boží?"],[29,"Odpověděl Ježíš a řekl jim: Totoť je to řekllo Boží, abyste věřili v toho, kteréhož on poslal."],[30,"řekli mu: Jakéž pak ty znamení činíš, abychom viděli a věřili tobě? Co děláš?"],[31,"Otcové naši jedli mannu na poušti, jakož psáno je: Chléb s nebe dal jim jísti."],[32,"řekl jim Ježíš: Amen, amen říkám vám: Ne Mojžíš dal vám chléb s nebe, ale Otec můj vám dává ten chléb s nebe pravý."],[33,"Protože chléb Boží ten je, kterýž sstupuje s nebe, a dává život světu."],[34,"řekli mu: Pane, dávejž nám chléb ten vždycky."],[35,"Ježíš pak řekl jim: Jáť jsem ten chléb života. Kdož přichází ke mně, nebude nikoli lačněti, a kdož věří ve mne, nebude žízniti nikdy."],[36,"Ale pověděl jsem vám, anobrž viděli jste mne, a nevěříte."],[37,"Všecko, což mi dává Otec, ke mně přijde, a toho, kdož ke mně přijde, nevyvrhu ven."],[38,"Protože jsem sstoupil s nebe, ne abych činil vůli svou, ale vůli toho, kterýž mne poslal."],[39,"Tatoť je pak vůle toho, kterýž mne poslal, Otcova, abych ničeho toho, což mi dal, neztratil, ale vzkřísil to v nejposlednější den."],[40,"tatoť je vůle toho, kterýž mne poslal, aby každý, kdož vidí Syna a věří v něj, měl život věčný. A jáť ho vzkřísím v den nejposlednější."],[41,"reptali Židé na něj, že řekl: Já jsem chléb ten, kterýž jsem s nebe sstoupil."],[42,"říkali: Zdaliž tento není Ježíš, syn Jozefův, jehož my otce i matku známe? Kterak pak dí tento: S nebe jsem sstoupil?"],[43,"odpověděl Ježíš a řekl jim: Nerepcete vespolek."],[44,"Žádný nemůž přijíti ke mně, jediné leč Otec můj, kterýž mne poslal, přitrhl by ho; a jáť ho vzkřísím v den nejposlednější."],[45,"Psáno je v prorocích: A budou všichni učeni od Boha. Protož každý, kdož slyšel od Otce a naučil se, jdeť ke mně."],[46,"Ne že by kdo viděl Otce, jediné ten, kterýž je od Boha, tenť viděl Otce."],[47,"Amen, amen říkám vám: Kdož věří ve mne, máť život věčný."],[48,"Jáť jsem ten chléb života."],[49,"Otcové vaši jedli mannu na poušti, a zemřeli."],[50,"Totoť je chléb ten s nebe sstupující. Kdož by koli ho jedl, neumřeť."],[51,"Jáť jsem ten chléb živý, kterýž jsem s nebe sstoupil. Bude-li kdo jísti ten chléb, živ bude na věky. A chléb, kterýž já dám, tělo mé je, kteréž já dám za život světa."],[52,"hádali se Židé vespolek, řkouce: Kterak tento může nám dáti tělo jísti?"],[53,"řekl jim Ježíš: Amen, amen říkám vám: Nebudete-li jísti těla Syna člověka a píti krve jeho, nemáte života v sobě."],[54,"Kdož jí mé tělo a pije mou krev, máť život věčný, a jáť ho vzkřísím v nejposlednější den."],[55,"Protože tělo mé právě je pokrm, a krev má právě je nápoj."],[56,"Kdo jí mé tělo a pije mou krev, ve mně přebývá a já v něm."],[57,"Jakož mne poslal ten živý Otec, a já živ jsem skrze Otce, tak kdož jí mne, i on živ bude skrze mne."],[58,"Totoť je ten chléb, kterýž s nebe sstoupil. Ne jako otcové vaši jedli mannu, a zemřeli. Kdož jí chléb tento, živť bude na věky."],[59,"Toto mluvil v škole, uče v Kafarnaum."]]},{"title":"Mnozí učedníci odcházejí","range":"Jan 6,60–71","thoughts":[],"verses":[[60,"mnozí z učedníků jeho, slyševše to, řekli: Tvrdáť je tato řeč. Kdo ji může slyšeti?"],[61,"Ale věda Ježíš sám v sobě, že by proto reptali učedlníci jeho, řekl jim: To vás uráží?"],[62,"Co pak, kdybyste uzřeli Syna člověka, an vstupuje, kdež prvé byl?"],[63,"Duch je, kterýž obživuje, těloť nic neprospívá. Slova, kteráž já mluvím vám, Duch jsou a život jsou."],[64,"Ale jsouť někteří z vás, ješto nevěří. Protože věděl Ježíš od počátku, kdo by byli nevěřící, a kdo by ho měl zraditi."],[65,"řekl: Protož jsem vám řekl, že žádný nemůže přijíti ke mně, leč by mu bylo dáno od Otce mého."],[66,"z toho mnozí z učedníků jeho odešli zpět, a nechodili s ním více."],[67,"řekl Ježíš ke dvanácti: Zdaliž i vy chcete odjíti?"],[68,"odpověděl mu Šimon Petr: Pane, k komu půjdeme? Slova věčného života máš."],[69,"my jsme uvěřili, a poznali, že jsi ty Kristus, Syn Boha živého."],[70,"Odpověděl jim Ježíš: Však jsem já vás dvanácte vyvolil, a jeden z vás ďábel je."],[71,"to řekl o Jidášovi Šimona Aškariotského; nebo ten ho měl zraditi, když byl jeden ze dvanácti."]]}];

JOHN_SECTIONS["7"] = [{"title":"Ježíš a jeho bratři","range":"Jan 7,1–9","thoughts":[],"verses":[[1,"pak chodil Ježíš po Galilei; nebo nechtěl býti v Judstvu, proto že ho hledali Židé zabiti."],[2,"byl blízko svátek Židovský, stánků."],[3,"řekli mu bratří jeho: Vyjdi odsud, a jdi do Judstva, ať i učedlníci tvoji vidí skutky tvé, kteréž činíš."],[4,"Nižádný zajisté v skrytě nic nedělá, kdož chce vidín býti. Protož ty, činíš-li takové věci, zjev se světu."],[5,"Protože ani bratří jeho nevěřili v něj."],[6,"dí jim Ježíš: Čas můj ještě nepřišel, ale čas váš vždycky je hotov."],[7,"Nemůžeť vás svět nenáviděti, ale mneť nenávidí; nebo já svědectví vydávám o něm, že skutkové jeho zlí jsou."],[8,"Jděte vy k svátku tomuto. Jáť ještě nepůjdu k svátku tomuto, nebo čas můj se ještě nenaplnil."],[9,"To pak pověděv jim, zůstal v Galilei."]]},{"title":"Ježíš na slavnosti stánků","range":"Jan 7,10–24","thoughts":[],"verses":[[10,"když odešli batří jeho, tehdy i on šel k svátku, ne zjevně, ale jako ukrytě."],[11,"Židé pak hledali ho v svátek, a říkali: Kde je onen?"],[12,"mnoho řečí bylo o něm v zástupu. Protože někteří říkali, že dobrý je, a jiní říkali: Není, ale svodí zástup."],[13,"Žádný však o něm nemluvil zjevně pro bázeň Židů."],[14,"Když pak již polovici svátku se vykonalo, vstoupil Ježíš do chrámu, a učil."],[15,"divili se Židé, řkouce: Kterak tento písmo umí, neučiv se?"],[16,"Odpověděl jim Ježíš a řekl: Mé učení neníť mé, ale toho, kterýž mne poslal."],[17,"Bude-li kdo chtíti vůli jeho činiti, tenť bude uměti rozeznati, je-li to učení z Boha, čili mluvím já sám od sebe."],[18,"Kdoť sám od sebe mluví, chvály své vlastní hledá, ale kdož hledá chvály toho, kterýž ho poslal, tenť pravdomluvný je, a nepravosti v něm není."],[19,"Však Mojžíš dal vám zákon, a žádný z vás neplní zákona. Proč mne hledáte zamordovati?"],[20,"Odpověděl zástup a řekl: Ďábelství máš. Kdo tě hledá zamordovati?"],[21,"Odpověděl Ježíš a řekl jim: Jeden skutek udělal jsem, a všichni se tomu divíte."],[22,"Však Mojžíš vydal vám obřízku, (ne že by z Mojžíše byla, ale z otců), a v sobotu obřezujete člověka."],[23,"Poněvadž člověk obřízku přijímá v sobotu, aby nebyl rušen zákon Mojžíšův, proč se na mne hněváte, že jsem celého člověka uzdravil v sobotu?"],[24,"Nesuďte podlé osoby, ale spravedlivý soud suďte."]]},{"title":"Spor o Ježíšův původ","range":"Jan 7,25–36","thoughts":[],"verses":[[25,"někteří z Jeruzalémských říkali: Zdaliž toto není ten, kteréhož hledají zabiti?"],[26,"aj, svobodně mluví a nic mu neříkají. Zdali již právě poznali knížata, že tento je právě Kristus?"],[27,"Ale o tomto víme, odkud je, Kristus pak když přijde, žádný nebude věděti, odkud by byl."],[28,"volal Ježíš v chrámě, uče a řka: A mne znáte, i odkud jsem, víte. A nepřišelť jsem sám od sebe, ale jestiť pravdomluvný ten, kterýž mne poslal, jehož vy neznáte."],[29,"Ale já znám ho, nebo od něj jsem, a on mne poslal."],[30,"hledali ho jíti, ale žádný nevztáhl ruky na něj, nebo ještě byla nepřišla hodina jeho."],[31,"Z zástupu pak mnozí uvěřili v něj, a říkali: Kristus když přijde, zda více divů činiti bude nad ty, kteréž tento činí?"],[32,"Slyšeli pak farizeové zástup, an o něm takové věci rozmlouvá, i poslali farizeové a přední kněží {biskupové} služebníky, aby ho jali."],[33,"řekl jim: Ještě maličký čas jsem s vámi, potom odejdu k tomu, kterýž mne poslal."],[34,"Hledati mne budete, ale nenaleznete, a kdež já budu, vy nemůžte přijíti."],[35,"řekli Židé k sobě vespolek: Kamtento půjde, že my ho nenalezneme? Zdali v rozptýlení pohanů půjde, a bude učiti pohany?"],[36,"Jaká je to řeč, kterouž promluvil: Hledati mne budete, ale nenaleznete, a kdež já budu, vy nemůžete přijíti?"]]},{"title":"Proudy živé vody","range":"Jan 7,37–39","thoughts":[],"verses":[[37,"V poslední pak den ten veliký svátku toho, stál Ježíš a volal, řka: Žízní-li kdo, poď ke mně, a napí se."],[38,"Kdož věří ve mne, jakož dí písmo, řeky z břicha jeho poplynou vody živé."],[39,"(A to řekl o Duchu, kteréhož měli přijíti věřící v něj; nebo ještě nebyl dán Duch svatý, proto že ještě Ježíš nebyl oslaven.)"]]},{"title":"Rozdělení mezi lidmi","range":"Jan 7,40–53","thoughts":[],"verses":[[40,"mnozí z zástupu uslyševše tu řeč, říkali: Tentoť je právě prorok ten."],[41,"Jiní říkali: Tentoť je Kristus. Ale někteří říkali: Zdaliž z Galilee přijde Kristus?"],[42,"Zdaž nepraví písmo, že z semene Davidova a z Betléma městečka, kdež býval David, přijíti má Kristus?"],[43,"tak různice v zástupu stala se pro něj."],[44,"Někteří pak z nich chtěli ho jíti, ale žádný nevztáhl ruky na něj."],[45,"přišli služebníci k předním kněžím {biskupům} a k farizeům, kteříž řekli jim: Proč jste ho nepřivedli?"],[46,"Odpověděli ti služebníci: Nikdy tak člověk nemluvil, jako tento člověk."],[47,"odpověděli jim farizeové: Zdali i vy jste svedeni?"],[48,"Zdaliž kdo z knížat uvěřil v něj aneb z farizeů?"],[49,"Než zástup ten, kterýž nezná zákona. Zlořečeníť jsou."],[50,"dí jim Nikodém, ten kterýž byl přišel k němu v noci, když byl jeden z nich:"],[51,"Zdali zákon náš soudí člověka, leč prvé uslyší od něj a zví, co by činil?"],[52,"Odpověděli a řekli mu: Nejsi-li i ty Galilejský? Ptej se a viz, žeť prorok z Galilee nepovstal."],[53,"šel jeden každý do domu svého."]]}];
JOHN_SECTIONS["8"] = [{"title":"Žena přistižená při cizoložství","range":"Jan 8,1–11","thoughts":[],"verses":[[1,"Ježíš pak odšel na horu Olivetskou."],[2,"na úsvitě zase přišel do chrámu, a celý lid sšel se k němu. A posadiv se, učil je."],[3,"přivedli k němu zákonníci a farizeové ženu v cizoložstvu popadenou, a postavivše ji v prostředku,"],[4,"Řekli mu: Mistře, tato žena je postižena při skutku, když cizoložila."],[5,"v zákoně Mojžíš přikázal nám takové kamenovati. Ty pak co pravíš?"],[6,"to řekli, pokoušejíce ho, aby ho mohli obžalovati. Ježíš pak skloniv se dolů, prstem psal na zemi."],[7,"když se nepřestávali otazovati jeho, zdvihl se a řekl jim: Kdo je z vás bez hříchu, nejprv hoď na ni kamenem."],[8,"znovu schýliv se, psal na zemi."],[9,"oni uslyševše to, a v svědomích svých obvinění když bylše, jeden po druhém odcházeli, počavše od starších až do posledních. A zůstal tu Ježíš sám, a ta žena u prostřed stojeci."],[10,"pozdvih se Ježíš, a žádného neviděv, než tu ženu, řekl jí: Ženo, kde jsou ti, kteříž na tebe žalovali? Žádný-li tě neodsoudil?"],[11,"Kteráž řekla: Žádný, Pane. A řekl jí Ježíš: Aniž já tebe odsuzuji. Jdiž a nehřeš více."]]},{"title":"Ježíš, světlo světa","range":"Jan 8,12–20","thoughts":[],"verses":[[12,"Ježíš znovu jim mluvil, řka: Já jsem světlo světa. Kdož mne následuje, nebude choditi v temnostech, ale bude míti světlo života."],[13,"řekli mu farizeové: Ty sám o sobě svědectví vydáváš, svědectví tvé není pravé."],[14,"Odpověděl Ježíš a řekl jim: Ačkoli já svědectví vydávám sám o sobě, pravé je svědectví mé; nebo vím, odkud jsem přišel, a kam jdu. Ale vy nevíte, odkud jsem přišel, aneb kam jdu."],[15,"Vy podlé těla soudíte, já nesoudím žádného."],[16,"bychť pak i já soudil, soud můj je pravý; nebo nejsem sám, ale jsem já a ten, kterýž mne poslal, Otec."],[17,"v zákoně vašem psáno je: Že dvou člověků svědectví pravé je."],[18,"Jáť svědectví vydávám sám o sobě, a svědectví vydává o mně ten, kterýž mne poslal, Otec."],[19,"řekli mu: Kdež je ten tvůj otec? Odpověděl Ježíš: Aniž mne znáte, ani Otce mého. Kdybyste mne znali, i Otce mého znali byste."],[20,"Tato slova mluvil Ježíš u pokladnice, uče v chrámě, a žádný ho nejal, nebo ještě byla nepřišla hodina jeho."]]},{"title":"Kam já jdu, vy nemůžete přijít","range":"Jan 8,21–30","thoughts":[],"verses":[[21,"řekl jim znovu Ježíš: Já jdu, a hledati budete mne, a v hříchu svém zemřete. Kam já jdu, vy nemůžete přijíti."],[22,"říkali Židé: Zdali se sám zabije, že praví: Kam já jdu, vy nemůžete přijíti?"],[23,"řekl jim: Vy z důlu jste, já s hůry jsem. Vy jste z tohoto světa, já nejsem z světa tohoto."],[24,"Protož jsem řekl vám: Že zemřetev hříších svých. Protože jestliže nebudete věřiti, že já jsem, zemřete v hříších svých."],[25,"řekli mu: Kdo jsi ty? A řekl jim Ježíš: To, což z počátku říkám vám."],[26,"Mnohoť mám o vás mluviti a souditi, ale ten, kterýž mne poslal, pravdomluvný je, a já, což jsem slyšel od něj, to mluvím na světě."],[27,"Ale neporozuměli, že by o Otci řekl jim."],[28,"Protož řekl jim Ježíš: Když povýšíte Syna člověka, tehdy poznáte, že já jsem. A sám od sebe nic nedělám, ale jakž mne naučil Otec můj, tak mluvím."],[29,"ten, kterýž mne poslal, se mnou je. Neopustilť mne samého Otec; nebo což je mu libého, to já činím vždycky."],[30,"Ty věci když mluvil, mnozí uvěřili v něj."]]},{"title":"Pravda vás osvobodí","range":"Jan 8,31–47","thoughts":[],"verses":[[31,"řekl Ježíš těm Židům, kteříž uvěřili mu: Jestliže vy zůstanete v řeči mé, právě učedlníci moji budete."],[32,"poznáte pravdu, a pravda vás vysvobodí."],[33,"odpověděli mu: Símě Abrahamovo jsme, a žádnému jsme nesloužili nikdy. A jakž ty díš: že svobodní budete?"],[34,"Odpověděl jim Ježíš: Amen, amen říkám vám: Že každý, kdož činí hřích, služebník je hřícha."],[35,"služebník nezůstává v domě na věky; Syn zůstává na věky."],[36,"Protož jestližeť vás Syn vysvobodí, právě svobodní budete."],[37,"Vím, že jste símě Abrahamovo, ale hledáte mne zabiti; nebo řeč má nemá místa u vás."],[38,"Já, což jsem viděl u Otce svého, mluvím; i vy tedy, co jste viděli u otce svého, činíte."],[39,"Odpověděli a řekli mu: Otec náš je Abraham. Dí jim Ježíš: Kdybyste synové Abrahamovi byli, činili byste skutky Abrahamovy."],[40,"Ale nyní hledáte mne zabiti, člověka toho, kterýž jsem pravdu mluvil vám, kterouž jsem slyšel od Boha. Tohoť Abraham nečinil."],[41,"Vy činíte skutky otce svého. A řekli mu: Myť z smilstva nejsme zplozeni, jednohoť Otce máme, Boha."],[42,"řekl jim Ježíš: Byť Bůh Otec váš byl, milovali byste mne. Protože já jsem z Boha pošel, a přišel jsem; aniž jsem sám od sebe přišel, ale on mne poslal."],[43,"Proč mluvení mého nechápáte? Proto že slyšeti nemůžete řeči mé."],[44,"Vy z otce ďábla jste, a žádosti otce svého chcete činiti. On byl vražedlník od počátku, a v pravdě nestál; nebo pravdy v něm není. Když mluví lež, z svého vlastního mluví; nebo lhář je a otec lži."],[45,"Já pak že pravdu říkám, nevěříte mi."],[46,"Kdo z vás uviní mne z hříchu? A poněvadž pravdu říkám, proč vy mi nevěříte?"],[47,"Kdo z Boha je, slova Boží slyší; protož vy neslyšíte, že z Boha nejste."]]},{"title":"Ježíš a Abraham","range":"Jan 8,48–59","thoughts":[],"verses":[[48,"odpověděli Židé a řekli mu: Zdaliž my dobře nepravíme, že jsi ty Samaritán, a ďábelství máš?"],[49,"Odpověděl Ježíš: Jáť ďábelství nemám, ale ctím Otce svého; než vy jste mne neuctili."],[50,"Jáť pak nehledám chvály své; jestiť, kdo hledá a soudí."],[51,"Amen, amen říkám, vám: Bude-li kdo zachovávati slovo mé, smrti neuzří na věky."],[52,"řekli mu Židé: Nyní jsme poznali, že ďábelství máš. Abraham umřel i proroci, a ty pravíš: Bude-li kdo zachovávati řeč mou, smrti neokusí na věky."],[53,"Zdali jsi ty větší otce našeho Abrahama, kterýž umřel? A proroci zemřeli. Kým ty se činíš?"],[54,"Odpověděl Ježíš: Chválím-liť já se sám, chvála má nic není. Jestiť Otec můj, kterýž mne chválí, o němž vy říkáte, že Bůh váš je."],[55,"Ale nepoznali jste ho, já pak ho znám. A kdybych řekl, že ho neznám, byl bych podobný vám, lhář. Ale známť ho, a řeč jeho zachovávám."],[56,"Abraham, otec váš, veselil se, aby viděl den můj, i viděl, a radoval se."],[57,"řekli mu Židé: Padesáti let ještě nemáš, a Abrahama jsi viděl?"],[58,"Řekl jim Ježíš: Amen, amen říkám vám: Prvé nežli Abraham byl, já jsem."],[59,"zchápali kamení, aby házeli na něj. Ježíš pak skryl se, a prošel skrze ně, vyšel z chrámu, a tak odšel."]]}];

JOHN_SECTIONS["9"] = [{"title":"Uzdravení slepého od narození","range":"Jan 9,1–12","thoughts":[],"verses":[[1,"pomíjeje, uviděl člověka slepého od narození."],[2,"otázali se ho učedlníci jeho, řkouce: Mistře, kdo zhřešil, tento-li, čili rodičové jeho, že se slepý narodil?"],[3,"Odpověděl Ježíš: Ani tento zhřešil, ani rodičové jeho, ale aby zjeveni byli skutkové Boží na něm."],[4,"Jáť musím dělati řekllo toho, kterýž mne poslal, dokudž den je. Přicházíť noc, když žádný nebude moci dělati."],[5,"Dokudž jsem na světě, světlo jsem světa."],[6,"To pověděv, plinul na zemi, a udělal bláto z sliny, i pomazal tím blátem oči slepého."],[7,"řekl mu: Jdi, umej se v rybníku Siloe, což se vykládá: Poslaný. A on šel a umyl se, i přišel, vida."],[8,"Sousedé pak a ti, kteříž ho prvé vídali slepého, řekli: Není-liž toto ten, kterýž sedával a žebrával?"],[9,"Jiní říkali, že ten je, a jiní, že je podoben k němu. Ale on řekl: Já jsem."],[10,"řekli mu: Kterak jsou otevříny oči tvé?"],[11,"On odpověděl a řekl: Člověk ten, kterýž slove Ježíš, bláto udělal, a pomazal očí mých, a řekl mi: Jdi k rybníku Siloe, a umej se. A odšel a umyv se, prohlédl jsem."],[12,"řekli mu: Kde je ten? Řekl: Nevím."]]},{"title":"Farizeové vyslýchají uzdraveného","range":"Jan 9,13–34","thoughts":[],"verses":[[13,"přivedli toho, kterýž někdy byl slepý, k farizeům."],[14,"Byla pak sobota, když Ježíš udělal bláto, a otevřel oči jeho."],[15,"otázali se ho znovu i farizeové, jak by prozřel. On pak řekl jim: Bláto položil na oči mé, a umyl jsem se, i vidím."],[16,"někteří z farizeů řekli: Ten člověk není z Boha, nebo neostříhá soboty. Jiní říkali: Kterak může člověk hříšný takové divy činiti? A byla různice mezi nimi."],[17,"Řekli znovu slepému: Co ty o něm pravíš, poněvadž otevřel oči tvé? A on řekl: Že prorok je."],[18,"nevěřili Židé o něm, by slepý býval a prozřel, až povolali rodičů toho, kterýž byl prozřel."],[19,"otázali se jich, řkouce: Jest-li tento syn váš, o kterémž vy říkáte, že by se slepý narodil? Kterakž pak nyní vidí?"],[20,"Odpověděli jim rodičové jeho a řekli: Vímeť, že tento je syn náš, a že se slepý narodil."],[21,"Ale jak nyní vidí, nevíme; aneb kdo otevřel oči jeho, myť nevíme. Máť léta, ptejte se ho, on sám za sebe mluviti bude."],[22,"Tak mluvili rodičové jeho, že se báli Židů; nebo již tak byli uložili Židé, aby, kdož by ho koli vyznal Kristem, vyobcován byl ze školy."],[23,"Protož řekli rodičové jeho: Máť léta, ptejte se jeho."],[24,"zavolali po druhé člověka toho, kterýž býval slepý, a řekli mu: Vzdej chválu Bohu. My víme, že člověk ten hříšník je."],[25,"odpověděl on a řekl: Jest-li hříšník, nevím, než to vím, že když byl slepý, nyní vidím."],[26,"řekli mu znovu: Coť udělal? Kterak otevřel oči tvé?"],[27,"Odpověděl jim: Již jsem vám pověděl, a neslyšeli jste? Což znovu chcete slyšeti? Zdaliž i vy chcete učedlníci jeho býti?"],[28,"zlořečili mu a řekli: Ty jsi učedník jeho, ale my jsme Mojžíšovi učedlníci."],[29,"My víme, že Mojžíšovi mluvil Bůh, tento pak nevíme, odkud je."],[30,"Odpověděl ten člověk a řekl jim: Toť je jistě divná věc, že vy nevíte, odkud je, a otevřel oči mé."],[31,"Víme pak, že Bůh hříšníků neslyší, ale kdo by ctitel Boží byl, a vůli jeho činil, tohoť slyší."],[32,"Od věků není slýcháno, aby kdo otevřel oči slepého narozeného."],[33,"Byť tento nebyl od Boha, nemohlť by nic udělat."],[34,"Odpověděli a řekli mu: Ty jsi celý se v hříších narodil, a ty nás učíš? A vyhnali ho ven."]]},{"title":"Duchovní slepota","range":"Jan 9,35–41","thoughts":[],"verses":[[35,"Uslyšel pak Ježíš, že ho vyhnali ven. A když ho nalezl, řekl mu: Věříš-liž ty v Syna Božího?"],[36,"Odpověděl on a řekl: A kdož je, Pane, abych věřil v něj?"],[37,"řekl mu Ježíš: A viděl jsi ho, a kterýž mluví s tebou, onť je."],[38,"on řekl: Věřím, Pane, a klaněl se mu."],[39,"řekl mu Ježíš: Na soud přišel jsem já na tento svět, aby ti, kteříž nevidí, viděli, a ti, kteříž vidí, aby slepí byli."],[40,"uslyšeli to někteří z farizeů, kteříž s ním byli, a řekli mu: Zdali i my slepí jsme?"],[41,"Řekl jim Ježíš: Byste slepí byli, hříchu byste neměli; ale nyní říkáte: Vidíme, protož hřích váš zůstává."]]}];

JOHN_SECTIONS["10"] = [{"title":"Dobrý pastýř","range":"Jan 10,1–21","thoughts":[],"verses":[[1,"Amen, amen říkám vám: Kdož nevchází dveřmi do ovčince ovcí, ale vchází jinudy, ten zloděj je a lotr."],[2,"Ale kdož vchází dveřmi, pastýř je ovcí."],[3,"Tomuť vrátný otvírá, a ovce hlas jeho slyší, a on svých vlastních ovec ze jména povolává, a vyvodí je."],[4,"jakž ovce své vlastní vypustí, před nimi jde, a ovce jdou za ním; nebo znají hlas jeho."],[5,"Cizího pak nikoli následovati nebudou, ale utekou od něj; nebo neznají hlasu cizích."],[6,"To podobenství pověděl jim Ježíš, ale oni nevěděli, co by to bylo, což jim mluvil."],[7,"znovu řekl jim Ježíš: Amen, amen říkám vám: Že já jsem dvéře ovcí."],[8,"Všickni, kolikž jich koli přede mnou příšlo, zloději jsou a lotři, ale neslyšeli jich ovce."],[9,"Já jsem dvéře. Skrze mne všel-li by kdo, spasen bude, a vejde i vyjde, a pastvu nalezne."],[10,"Zloděj nepřichází, než aby kradl a mordoval a hubil; já jsem přišel, aby život měly, a hojně měly."],[11,"Já jsem ten pastýř dobrý. Dobrý pastýř duši svou pokládá za ovce."],[12,"Ale nájemník a ten, kterýž není pastýř, jehož nejsou ovce vlastní, vida vlka, an jde, i opouští ovce i utíká, a vlk lapá a rozhání ovce."],[13,"Nájemník pak utíká; nebo nájemník je, a nemá péče o ovce."],[14,"Já jsem ten dobrý pastýř, a známť své, a znajíť mne mé."],[15,"Jakož mne zná Otec, a já znám Otce, a duši svou pokládám za ovce."],[16,"mámť i jiné ovce, kteréž nejsou z tohoto ovčince. A tyť musím přivesti; nebo hlas můj slyšeti budou. A budeť jeden ovčinec a jeden pastýř."],[17,"Protož mne Otec miluje, že já pokládám duši svou, abych ji zase vzal."],[18,"Nižádnýť jí nebéře ode mne, ale já pokládám ji sám od sebe. Mám moc položiti ji, a mám moc zase vzíti ji. To přikázaní vzal jsem od Otce svého."],[19,"stala se znovu různice mezi Židy pro ty řeči."],[20,"říkali mnozí z nich: Ďábelství má a blázní. Co ho posloucháte?"],[21,"Jiní říkali: Tato slova nejsou ďábelství mělaího. Zdaliž ďábelství může slepých oči otvírati?"]]},{"title":"Ježíš o svém vztahu k Otci","range":"Jan 10,22–39","thoughts":[],"verses":[[22,"Bylo pak posvícení v Jeruzalémě, a zima byla."],[23,"procházel se Ježíš v chrámě po síňci Šalomounově."],[24,"obstoupili ho Židé, a řekli mu: Dokudž duši naši držíš: Jestliže jsi ty Kristus, pověz nám zjevně."],[25,"Odpověděl jim Ježíš: Pověděl jsem vám, a nevěříte. Skutkové, kteréž já činím ve jménu Otce svého, tiť svědectví vydávají o mně."],[26,"Ale vy nevěříte, nebo nejste z ovcí mých, jakož jsem vám pověděl."],[27,"Ovceť mé hlas můj slyší, a já je znám, a následujíť mne."],[28,"jáť život věčný dávám jim, a nezahynouť na věky, aniž jich kdo vytrhne z ruky mé."],[29,"Otec můj, kterýž mi je dal, větší je nade všecky, a žádnýť jich nemůže vytrhnouti z ruky Otce mého."],[30,"Já a Otec jedno jsme."],[31,"zchápali znovu kamení Židé, aby ho kamenovali."],[32,"Odpověděl jim Ježíš: Mnohé dobré skutky ukázal jsem vám od Otce svého. Pro který z těch skutků kamenujete mne?"],[33,"Odpověděli mu Židé, řkouce. Pro dobrý skutek tebe nekamenujeme, ale pro rouhání, totiž že ty, člověk když byl, děláš se Bohem."],[34,"Odpověděl jim Ježíš: Však psáno je v zákoně vašem: Já jsem řekl: Bohové jste."],[35,"Poněvadž ty nazval bohy, k nimž řeč Boží stala se, a nemůže zrušeno býti písmo,"],[36,"Mně pak, kteréhož posvětil Otec a poslal na svět, vy říkáte: Rouháš se, že jsem řekl: Syn Boží jsem?"],[37,"Nedělám-liť skutků Otce svého nevěřte mi."],[38,"Pakliť činím, byste pak mně nevěřili, skutkům věřte, abyste poznali a věřili, že"],[39,"znovu hledali ho jíti, ale vyšel z rukou jejich."]]},{"title":"Za Jordánem","range":"Jan 10,40–42","thoughts":[],"verses":[[40,"odšel znovu za Jordán na to místo, kdež nejprvé Jan křtil, a pozůstal tam."],[41,"přišli k němu mnozí, a říkali: Jan zajisté žádného divu neučinil, ale všechno, cožkoli mluvil Jan o tomto, pravé bylo."],[42,"mnozí tam uvěřili v něj."]]}];

JOHN_SECTIONS["11"] = [{"title":"Smrt Lazara","range":"Jan 11,1–16","thoughts":[],"verses":[[1,"Byl pak nemocen nějaký Lazar z Betany, z městečka Marie a Marty, sestry hoí."],[2,"to byla ta Maria, kteráž pomazala Pána mastí, a vytřela nohy jeho vlasy svými, hoíž bratr Lazar byl nemocen."],[3,"poslaly k němu ty sestry, řkouce: Pane, aj, ten, kteréhož miluješ, nemocen je."],[4,"uslyšav to Ježíš, řekl: nemoc ta není k smrti, ale pro slávu Boží, aby oslaven byl Syn Boží skrze ni."],[5,"Miloval pak Ježíš Martu i sestru hoí i Lazara."],[6,"jakž uslyšel, že by nemocen byl,tedy pozůstal za dva dni na tom místě, kdež byl."],[7,"pak dí učedníkům: Pojďme zase do Judstva."],[8,"Řekli mu učedlníci: Mistře, nyní hledali tě Židé kamenovati, a zase tam chceš jíti?"],[9,"Odpověděl Ježíš: Zdaliž není dvanácte hodin za den? Chodí-li kdo ve dne, neurazí se; nebo světlo tohoto světa vidí."],[10,"Pakliť by kdo chodil v noci, urazíť se; nebo světla není v něm."],[11,"To pověděl, a potom dí jim: Lazar, přítel náš, spí, ale jduť, abych ho ze sna probudil."],[12,"řekli učedlníci jeho: Pane, spí-liť, zdráv bude."],[13,"Ale Ježíš řekl o smrti jeho, oni pak domnívali se, že by o spání sna mluvil."],[14,"řekl jim Ježíš zjevně: Lazar umřel."],[15,"raduji se pro vás, že jsem tam nebyl, abyste věřili. Ale pojďme k němu."],[16,"řekl Tomáš, kterýž slove Didymus, spoluučedlníkum: Pojďme i my, abychom zemřeli s ním."]]},{"title":"Ježíš je vzkříšení a život","range":"Jan 11,17–37","thoughts":[],"verses":[[17,"Přišel tedy Ježíš, a nalezl ho již čtyři dni v hrobě pochovaného."],[18,"Byla pak Betany blízko od Jeruzaléma, okolo honů patnácte."],[19,"Mnozí pak z Židů byli přišli k Martě a Marii, aby je těšili pro bratra jejich."],[20,"Marta, jakž uslyšela, že Ježíš jde, vyšla proti němu, ale Maria doma seděla."],[21,"řekla Marta Ježíšovi: Pane, kdybys ty byl zde, bratr můj byl by neumřel."],[22,"Ale i nyníť vím, že cožkoli požádal bys od Boha, dá tobě Bůh."],[23,"Dí jí Ježíš: Vstaneť bratr tvůj."],[24,"Řekla mu Marta: Vím, že vstane při vzkříšení v den nejposlednější."],[25,"Řekl jí Ježíš: já jsem vzkříšení i život. Kdo věří ve mne, byť pak i umřel, živ bude."],[26,"každý, kdož je živ, a věří ve mne, neumřeť na věky. Věříš-li tomu?"],[27,"Řekla mu: Ovšem, Pane, já jsem uvěřila, že jsi ty Kristus, Syn Boží, kterýž měl přijíti na svět."],[28,"když to pověděla, odešla a zavolala tajně Marie, sestry své, řkuci: Mistr zde je, a volá tebe."],[29,"Ona jakž uslyšela, vstala rychle, a šla k němu."],[30,"Ještě pak byl Ježíš nepřišel do městečka, ale byl na tom místě, kdež vyšla byla proti němu Marta."],[31,"Židé, kteříž s ní byli v domě, a těšili ji, když vidělše Marii, že rychle vstala a vyšla, šli za ní, řkouce: Jde k hrobu, aby tam plakala."],[32,"Ale Maria, když tam přišla, kdež byl Ježíš, když uvidělši ho, padla k nohám jeho, řkuci mu: Pane, bys ty byl zde, bratr můj byl by neumřel."],[33,"Ježíš pak jakž uviděl, ana pláče, i Židy, kteříž byli s ní přišli, ani plačí, zastonal duchem, a zkormoutil se."],[34,"řekl: Kdež jste ho položili? Řkou mu: Pane, poď a pohleď."],[35,"zaplakal Ježíš."],[36,"řekli Židé: Hle, jak ho miloval!"],[37,"Někteří pak z nich řekli: Nemohl-liž tento, kterýž otevřel oči slepého, udělat aby tento neumřel?"]]},{"title":"Vzkříšení Lazara","range":"Jan 11,38–44","thoughts":[],"verses":[[38,"Ježíš pak znovu zastonav sám v sobě, přišel k hrobu. Byla pak jeskyně, a kámen byl svrchu položen na ni."],[39,"Dí Ježíš: Zdvihněte kámen. Řekla mu Marta, sestra toho mrtvého: Pane, jižť smrdí; nebo čtyři dni v hrobě je."],[40,"Dí jí Ježíš: Všakť jsem řekl, že budeš-li věřiti, uzříš slávu Boží."],[41,"zdvihli kámen, kdež byl ten mrtvý pochován. Ježíš pak pozdvihl zhůru očí a řekl: Otče, děkuji tobě, že jsi mne slyšel."],[42,"Já zajisté vím, že mne vždycky slyšíš, ale pro zástup, kterýž okolo stojí, řekl jsem, aby věřili, že jsi ty mne poslal."],[43,"to pověděv, zavolal hlasem velikým: Lazaře, poď ven."],[44,"vyšel ten, kterýž byl umřel, měl svázané ruce i nohy rouchami, a tvář jeho šatem byla obvinuta. Řekl jim Ježíš: Rozvěžtež ho, a nechte, ať odejde."]]},{"title":"Rozhodnutí Ježíše zabít","range":"Jan 11,45–57","thoughts":[],"verses":[[45,"mnozí z Židů, kteříž byli přišli k Marii, když vidělše, co udělal Ježíš, uvěřili v něj."],[46,"Někteří pak z nich odešli k farizeům, a pověděli jim, co udělal Ježíš."],[47,"sešli se přední kněží {biskupové} a farizeové v radu, a říkali: Co činíme? Protože tento člověk divy mnohé činí."],[48,"Necháme-li ho tak, všichni uvěří v něj, i přijdou Římané, a odejmou místo naše i lid."],[49,"Jeden pak z nich, Kaifáš, nejvyšším knězem {biskupem} když byl toho léta, řekl jim: Vy nic nevíte,"],[50,"Aniž přemyšlujete, že je užitečné nám, aby jeden člověk umřel za lid, a ne, aby celý tento národ zahynul."],[51,"Toho pak neřekl sám od sebe, ale nejvyšším knězem {biskupem} když byl léta toho, prorokoval, že měl Ježíš umříti za tento národ."],[52,"netoliko za tento národ, ale také, aby syny Boží rozptýlené shromáždil v jedno."],[53,"Protož od toho dne radu společně drželi, aby ho zabili."],[54,"Ježíš pak již nechodil zjevně mezi Židy, ale odšel odtud do krajiny blízko pouště, do města, kteréž slove Efraim, a tu bydlil s učedníky svými."],[55,"Byla pak blízko velikanoc Židovská. A šli mnozí do Jeruzaléma z krajiny té před velikonocí, aby se očistili."],[56,"hledali Ježíše, a rozmlouvali vespolek, v chrámě stojíce: Co se vám zdá, že nepřišel k svátku?"],[57,"Vydali pak byli přední kněží {biskupové} a farizeové mandát, jestliže by kdo zvěděl, kde by byl, aby pověděl, aby ho jali."]]}];

JOHN_SECTIONS["12"] = [{"title":"Pomazání v Betanii","range":"Jan 12,1–11","thoughts":[],"verses":[[1,"Ježíš šestý den před velikonocí přišel do Betany, kdež byl Lazar ten, kterýž byl umřel, jehož vzkřísil z mrtvých."],[2,"připravili mu tu večeři, a Marta posluhovala, Lazar pak byl jeden z stolících s ním."],[3,"Maria pak vzavši libru masti drahé z nardu výborného, pomazala noh Ježíšových, a vytřela vlasy svými nohy jeho. A naplněn je dům vůní té masti."],[4,"řekl jeden z učedníků jeho, Jidáš Šimona Aškariotského, kterýž ho měl zraditi:"],[5,"Proč tato mast není prodána za tři sta peněz, a není dáno chudým?"],[6,"To pak řekl, ne že by měl péči o chudé, ale že zlodej byl, a měšec měl, a to, což do něj kladeno bylo, nosil."],[7,"řekl Ježíš: Nech jí, ke dni pohřbu mého zachovala to."],[8,"Protože chudé vždycky máte s sebou, ale mne ne vždycky míti budete."],[9,"Zvěděl pak zástup veliký z Židů, že by tu byl. A přišli, ne pro Ježíše toliko, ale také aby Lazara viděli, kteréhož byl vzkřísil z mrtvých."],[10,"Radili se pak přední kněží {biskupové}, aby i Lazara zamordovali."],[11,"Protože mnozí z Židů odcházeli pro něj, a uvěřili v Ježíše."]]},{"title":"Vjezd do Jeruzaléma","range":"Jan 12,12–19","thoughts":[],"verses":[[12,"Nazejtří mnohý zástup, kterýž byl přišel k svátku, když uslyšeli, že Ježíš jde do Jeruzaléma,"],[13,"Nabrali ratolestí palmových, a vyšli proti němu, a volali: Hosanna, požehnaný, kterýž se béře ve jménu Páně, král Izraelský."],[14,"dostav Ježíš oslátka, vsedl na ně, jakož psáno je:"],[15,"Neboj se, dcero Sionská, aj, král tvůj béře se, na oslátku sedě."],[16,"Tomu pak nesrozuměli učedlníci jeho sprvu, ale když oslaven byl Ježíš, tedy se rozpomenuli, že to psáno bylo o něm, a že mu to učinili."],[17,"Vydával pak svědectví zástup, kterýž byl s ním, že Lazara povolal z hrobu, a vzkřísil ho z mrtvých."],[18,"Protož i v cestu vyšel mu zástup, když slyšeli, že by ten div udělal."],[19,"farizeové říkali mezi sebou: Vidíte-li, že nic neprospíváte? Hle, svět postoupil po něm."]]},{"title":"Řekové chtějí vidět Ježíše","range":"Jan 12,20–36","thoughts":[],"verses":[[20,"Byli pak někteří Řekové z těch, kteříž přicházívali, aby se modlili v svátek."],[21,"Ti tedy přistoupili k Filipovi, kterýž byl od Betsaidy Galilejské, a prosili ho, řkouce: Pane, chtěli bychom Ježíše viděti."],[22,"Přišel Filip a pověděl Ondřejovi, Ondřej pak zase a Filip pověděli Ježíšovi."],[23,"Ježíš odpověděl jim, řka: Přišlať hodina, aby oslaven byl Syn člověka."],[24,"Amen, amen říkám vám: Zrno pšeničné padna v zemi, neumře-li, onoť samo zůstane, a pakliť umře, mnohý užitek přinese."],[25,"Kdož miluje duši svou, ztratíť ji; a kdož nenávidí duše své na tomto světě, k životu věčnému ostříhá jí."],[26,"Slouží-li mi kdo, následujž mne; a kdež jsem já, tuť i můj služebník bude. A bude-li mi kdo sloužiti, poctíť ho Otec."],[27,"Nyní duše má zkormoucena je, a což řeklm? Otče, vysvoboď mne z této hodiny. Ale proto jsem přišel k hodině této."],[28,"Otče, oslaviž jméno své. Potom přišel hlas s nebe: A oslavil jsem, i ještě oslavím."],[29,"Ten pak zástup, kterýž tu stál a slyšel, řekl: Zahřmělo. Jiní říkali: Anděl k němu mluvil."],[30,"Odpověděl Ježíš a řekl: Ne pro mneť hlas tento se stal, ale pro vás."],[31,"Nyníť je soud světa tohoto, nyní kníže světa tohoto vyvrženo bude ven."],[32,"já budu-liť povýšen od země, všecky potáhnu k sobě."],[33,"(To pak pověděl, znamenaje, kterou by smrtí měl umříti.)"],[34,"Odpověděl mu zástup: My jsme slýchali z zákona, že Kristus zůstává na věky, a jakž ty pravíš, že musí býti povýšen Syn člověka? Kdo je to Syn člověka?"],[35,"řekl jim Ježíš: Ještě na malý čas světlo s vámi je. Choďte, dokud světlo máte, ať vás tma nezachvátí; nebo kdo chodí ve tmách, neví, kam jde."],[36,"Dokud světlo máte, věřte v světlo, abyste synové světla byli. Toto pověděl Ježíš, a odšel, skryl se před nimi."]]},{"title":"Nevíra lidu","range":"Jan 12,37–43","thoughts":[],"verses":[[37,"ačkoli tak mnohá znamení činil před nimi, však neuvěřili v něj,"],[38,"Aby se naplnila řeč Izaiáše proroka, kterouž pověděl: Pane, kdo uvěřil kázaní našemu, a rámě Páně komu je zjeveno?"],[39,"Protoť nemohli věřiti, že znovu Izaiáš řekl:"],[40,"Oslepil oči jejich, a zatvrdil srdce jejich, aby očima neviděli, a srdcem nerozuměli, a neobrátili se, abych jich neuzdravil."],[41,"To pověděl Izaiáš, když viděl slávu jeho, a mluvil o něm."],[42,"ačkoli mnozí i z knížat uvěřili v něj, však pro farizee nevyznávali, aby ze školy nebyli vyobcování."],[43,"Protože milovali slávu lidskou více než slávu Boží."]]},{"title":"Ježíšovo poslední veřejné slovo","range":"Jan 12,44–50","thoughts":[],"verses":[[44,"Ježíš pak zvolal a řekl: Kdo věří ve mne, ne ve mneť věří, ale v toho, kterýž mne poslal."],[45,"kdož vidí mne, vidí toho, kterýž mne poslal."],[46,"Já světlo na svět jsem přišel, aby žádný, kdož věří ve mne, ve tmě nezůstal."],[47,"slyšel-liť by kdo slova má, a nevěřil by, jáť ho nesoudím; nebo nepřišel jsem, abych soudil svět, ale abych spasil svět."],[48,"Kdož mnou pohrdá, a nepřijímá slov mých, máť, kdo by ho soudil. Slova, kteráž jsem mluvil, tať ho souditi budou v nejposlednější den."],[49,"Protože já sám od sebe jsem nemluvil, ale ten, kterýž mne poslal, Otec, on mi přikázaní dal, co bych měl praviti a mluviti."],[50,"vím, že přikázaní jeho je život věčný. A protož, což já mluvím, jakž mi pověděl Otec, takť mluvím."]]}];

JOHN_SECTIONS["13"] = [{"title":"Ježíš umývá učedníkům nohy","range":"Jan 13,1–20","thoughts":[],"verses":[[1,"Před svátkem pak velikonočním, věda Ježíš, že přišla hodina jeho, aby šel z tohoto světa k Otci, milovav své, kteříž byli na světě, až do konce je miloval."],[2,"když večeřeli, (a ďábel již byl vnukl v srdce Jidáše Šimona Aškariotského, aby ho zradil),"],[3,"Věda Ježíš, že mu Otec všechno v ruce dal, a že od Boha vyšel a k Bohu jde,"],[4,"Vstal od večeře, a složil oděv, a vzav rouchu, přepásal se."],[5,"nalil vody do medenice, i počal umývati nohy učedníků a vytírati rouchou, kterouž byl přepásán."],[6,"přišel k Šimonovi Petrovi, a on řekl mu: Pane, ty mi chceš nohy mýti?"],[7,"Odpověděl Ježíš a řekl mu: Co já činím, ty nevíš nyní, ale potom zvíš."],[8,"Dí mu Petr: Nebudeš ty mýti noh mých na věky. Odpověděl mu Ježíš: Neumyji-liť tebe, nebudeš míti řekllu se mnou."],[9,"Dí mu Šimon Petr: Pane, netoliko nohy mé, ale i ruce i hlavu."],[10,"Řekl mu Ježíš: Kdož je umyt, nepotřebuje, než aby nohy umyl; nebo čist je celý. A vy čisti jste, ale ne všichni."],[11,"Protože věděl o zrádci svém; protož řekl: Ne všichni čisti jste."],[12,"Když pak umyl nohy jejich, a vzal oděv své, posadiv se za stůl zase, řekl jim: Víte-liž, co jsem udělal vám?"],[13,"Vy nazýváte mne Mistrem a Pánem, a dobře říkáte, jsemť zajisté."],[14,"Poněvadž tedy já umyl jsem nohy vaše, Pán a Mistr, i vy máte jeden druhému nohy umývati."],[15,"Příklad zajisté dal jsem vám, abyste, jakož jsem já udělal vám, i vy činili."],[16,"Amen, amen říkám vám: Není služebník větší nad pána svého, ani posel větší nežli ten, kdož ho poslal."],[17,"Znáte-li tyto věci, blahoslavení jste, budete-li je činiti."],[18,"Ne o všechť vás říkám. Já vím, které jsem vyvolil, ale musíť se naplniti písmo: Ten, kdož jí chléb se mnou, pozdvihl proti mně paty své."],[19,"Nyní říkám, vám, prvé než by se stalo, abyste, když se stane, uvěřili, že já jsem."],[20,"Amen, amen říkám vám: Kdo přijímá toho, kohož bych já poslal, mneť přijímá; a kdož mne přijímá, přijímá toho, kterýž mne poslal."]]},{"title":"Označení zrádce","range":"Jan 13,21–30","thoughts":[],"verses":[[21,"to pověděv Ježíš, zkormoutil se v duchu, a osvědčil, řka: Amen, amen říkám vám, že jeden z vás mne zradí."],[22,"učedlníci vzhlédali na sebe vespolek, pochybujíce, o kom by to řekl."],[23,"Byl pak jeden z učedníků Ježíšových, kterýž zpolehl na klíně jeho, ten, jehož miloval Ježíš."],[24,"Protož tomu návěští dal Šimon Petr, aby se zeptal, kdo by to byl, o němž praví."],[25,"on odpočívaje na prsech Ježíšových, řekl mu: Pane, kdo je?"],[26,"Odpověděl Ježíš: Ten je, komuž já omočené skyvy chleba podám. A omočiv skyvu chleba, podal Jidášovi, synu Šimona Aškariotského."],[27,"hned po té skyvě chleba vstoupil do něj satan. A řekl mu Ježíš: Co činíš, čiň spěšně."],[28,"Tomu pak žádný z přísedících nerozuměl, k čemu by mu to řekl."],[29,"Protože někteří se domnívali, poněvadž Jidáš měšec měl, že by mu řekl Ježíš: Nakup těch věcí, kterýchž je nám potřebí k svátku, aneb aby něco chudým dal."],[30,"on vzav skyvu chleba, hned vyšel, A byla noc."]]},{"title":"Nové přikázání","range":"Jan 13,31–35","thoughts":[],"verses":[[31,"Když pak on vyšel, dí Ježíš: Nyníť oslaven je Syn člověka, a Bůh oslaven je v něm."],[32,"poněvadž Bůh oslaven je v něm, i Bůh oslaví ho sám v sobě, a to hned oslaví ho."],[33,"Synáčkové, ještě maličko s vámi jsem. Hledati mne budete, ale jakož jsem řekl Židům: Kam já jdu, vy nemůžete přijíti, i vám říkám nyní."],[34,"Přikázaní nové dávám vám, abyste se milovali vespolek; jakož já miloval jsem vás, abyste i vy milovali jeden druhého."],[35,"Po tomť poznají všichni, že jste moji učedlníci, budete-li míti lásku jedni k druhým."]]},{"title":"Ježíš předpovídá Petrovo zapření","range":"Jan 13,36–38","thoughts":[],"verses":[[36,"Dí mu Šimon Petr: Pane, kam jdeš? Odpověděl mu Ježíš: Kam jdu, nemůžeš ty nyní jíti za mnou, ale půjdeš potom."],[37,"Dí mu Petr: Pane, proč bych nemohl nyní jíti za tebou? Duši svou za tebe položím."],[38,"Odpověděl mu Ježíš: Duši svou za mne položíš? Amen, amen říkám tobě: Nezazpíváť kohout, až mne třikrát zapříš."]]}];

JOHN_SECTIONS["14"] = [{"title":"Ježíš je cesta, pravda a život","range":"Jan 14,1–14","thoughts":[],"verses":[[1,"Nermutiž se srdce vaše. Věříte v Boha, i ve mne věřte."],[2,"V domě Otce mého příbytkové mnozí jsou. Byť nebylo tak, pověděl bych vám."],[3,"Jduť, abych vám připravil místo. A když odejdu, a připravím vám místo, zase přijdu, a poberu vás k sobě samému, abyste, kde jsem já, i vy byli."],[4,"kam já jdu, víte, i cestu víte."],[5,"Dí mu Tomáš: Pane, nevíme, kam jdeš. A jak můžeme cestu věděti?"],[6,"Dí mu Ježíš: Já jsem ta cesta, i pravda, i život. Žádný nepřichází k Otci než skrze mne."],[7,"Byste znali mne, také i Otce mého znali byste; a již nyní ho znáte, a viděli jste ho."],[8,"Řekl mu Filip: Pane, ukaž nám Otce, a dostiť je nám."],[9,"Dí mu Ježíš: Tak dlouhý čas s vámi jsem, a nepoznal jsi mne? Filipe, kdož vidí mne, vidí Otce, a jakž ty pravíš: Ukaž nám Otce?"],[10,"Nevěříš, že já v Otci a Otec ve mně je? Slova, kteráž já mluvím vám, sám od sebe nemluvím, ale Otec ve mně přebývaje, onť činí skutky."],[11,"Věřtež mi, že jsem já v Otci a Otec ve mně; aneb aspoň pro ty samy skutky věřte mi."],[12,"Amen, amen říkám vám: Kdož věří ve mne, skutky, kteréž já činím, i on činiti bude, a větší nad ty činiti bude; nebo já jdu k Otci svému."],[13,"jestliže byste co prosili ve jménu mém, toť udělám, aby oslaven byl Otec v Synu."],[14,"Budete-li zač prositi ve jménu mém, jáť udělám."]]},{"title":"Příslib Ducha svatého","range":"Jan 14,15–26","thoughts":[],"verses":[[15,"Milujete-li mne, přikázaní mých ostříhejte."],[16,"jáť prositi budu Otce, a jiného Utěšitele dá vám, aby s vámi zůstal na věky,"],[17,"Toho Ducha pravdy, jehož svět nemůže přijíti. Protože nevidí ho, aniž ho zná, ale vy znáte ho, neboť u vás přebývá, a v vás bude."],[18,"Neopustímť vás sirotků, přijduť k vám."],[19,"Ještě maličko, a svět mne více neuzří, ale vy uzříte mne; nebo já živ jsem, i vy živi budete."],[20,"V ten den vy poznáte, že já jsem v Otci svém, a vy ve mně, a já v vás."],[21,"Kdož by měl přikázaní má, a ostříhal jich, onť je ten, kterýž mne miluje. A kdož mne miluje, milován bude od Otce mého, a jáť ho budu milovati, a zjevím mu samého sebe."],[22,"Řekl mu Judas, ne onen Aškariotský: Pane, jakž je to, že sebe nám zjeviti chceš, a ne světu?"],[23,"Odpověděl Ježíš a řekl mu: Miluje-li mne kdo, slova mého ostříhati bude, a Otec můj bude ho milovati, a k němu přijdeme, a příbytek u něj uděláme."],[24,"Kdožť nemiluje mne, slov mých neostříhá; a slovo, kteréž slyšíte, neníť mé, ale toho, kterýž mne poslal, Otcovo."],[25,"Toto mluvil jsem vám, u vás přebývaje."],[26,"Utěšitel pak, ten Duch svatý, kteréhož pošle Otec ve jménu mém, onť vás naučí všemu, a připomeneť vám všechno, což jsem koli mluvil vám."]]},{"title":"Ježíš dává svůj pokoj","range":"Jan 14,27–31","thoughts":[],"verses":[[27,"Pokoj zůstavuji vám, pokoj svůj dávám vám; ne jako svět dává, já dávám vám. Nermutiž se srdce vaše, ani strachuj."],[28,"Slyšeli jste, že já řekl jsem vám: Jdu, a zase přijdu k vám. Kdybyste mne milovali, radovali byste se jistě, že jsem řekl: Jdu k Otci; nebo Otec větší je nežli já."],[29,"nyní pověděl jsem vám, prvé než by se stalo, abyste, když se stane, uvěřili."],[30,"Již nemnoho mluviti budu s vámi; neboť jde kníže tohoto světa, ale nemáť nic na mně."],[31,"Ale aby poznal svět, že miluji Otce, a jakož mi přikázal Otec, tak činím. Vstaňte, pojďme odtud."]]}];
JOHN_SECTIONS["15"] = [{"title":"Pravý vinný kmen","range":"Jan 15,1–17","thoughts":[],"verses":[[1,"Já jsem ten vinný kmen pravý, a Otec můj vinař je."],[2,"Každou ratolest, kteráž ve mně nenese ovoce, odřezuje, a každou, kteráž nese ovoce, čistí, aby hojnější ovoce nesla."],[3,"Již vy čisti jste pro řeč, kterouž jsem mluvil vám."],[4,"Zůstaňtež ve mně, a já v vás. Jakož ratolest nemůže nésti ovoce sama od sebe, nezůstala-li by při kmenu, takž ani vy, leč zůstanete ve mně."],[5,"Já jsem vinný kmen a vy ratolesti. Kdo zůstává ve mně, a já v něm, ten nese ovoce mnohé; nebo beze mne nic nemůžete udělat."],[6,"Nezůstal-li by kdo ve mně, vyvržen bude ven jako ratolest, a uschneť, a budouť sebrány, a na oheň uvrženy, a shoříť."],[7,"Zůstanete-li ve mně, a slova má zůstanou-liť v vás, což byste koli chtěli, proste, a staneť se vám."],[8,"V tomť bývá oslaven Otec můj, když ovoce nesete hojné, a budete moji učedlníci."],[9,"Jakož miloval mne Otec, i já miloval jsem vás. Zůstaňtež v milování mém."],[10,"Budete-li zachovávati přikázaní má, zůstanete v mém milování, jakož i já přikázaní Otce svého zachoval jsem, i zůstávám v jeho milování."],[11,"Toto mluvil jsem vám, aby radost má zůstávala v vás, a radost vaše byla plná."],[12,"Totoť je přikázaní mé, abyste se milovali vespolek, jako já miloval jsem vás."],[13,"Většího milování nad to žádný nemá, než aby duši svou položil za přátely své."],[14,"Vy přátelé moji jste, uděláte-li to, což já přikazuji vám."],[15,"Nebudu vás více nazývati služebníky, nebo služebník neví, co by činil pán jeho. Ale vás jsem nazval přátely, nebo všechno, což jsem koli slyšel od Otce svého, oznámil jsem vám."],[16,"Ne vy jste mne vyvolili, ale já jsem vás vyvolil, a postavil, abyste šli a ovoce přinesli, a ovoce vaše aby zůstalo, aby zač byste koli prosili Otce ve jménu mém, dal vám."],[17,"Toto přikazuji vám, abyste se milovali vespolek."]]},{"title":"Nenávist světa","range":"Jan 15,18–27","thoughts":[],"verses":[[18,"Jestližeť vás svět nenávidí, víte, žeť mne prvé než vás v nenávisti měl."],[19,"Byste byli z světa, svět, což je jeho, miloval by; že pak nejste z světa, ale já z světa vyvolil jsem vás, protož vás svět nenávidí."],[20,"Pamatujte na tu řeč, kterouž jsem já mluvil vám: Neníť služebník větší nežli pán jeho. Poněvadž se mně protivili, i vámť se protiviti budou; poněvadž řeči mé šetřili, i vaší šetřiti budou."],[21,"Ale toto všechno učiní vám pro jméno mé; nebo neznají toho, kterýž mne poslal."],[22,"Kdybych byl nepřišel, a nemluvil jim, hříchu by neměli; ale nyní výmluvy nemají z hříchu svého."],[23,"Kdož mne nenávidí, i Otceť mého nenávidí."],[24,"Bych byl skutků nečinil mezi nimi, jichž žádný jiný nečinil, hříchu by neměli; ale nyní i viděli, i nenáviděli i mne i Otce mého."],[25,"Ale aby se naplnila řeč, kteráž v zákoně jejich napsána je: Že v nenávisti měli mne darmo."],[26,"Když pak přijde ten Utěšitel, kteréhož já pošli vám od Otce, Duch pravdy, kterýž od Otce pochází, tenť svědectví vydávati bude o mně."],[27,"Ano i vy svědectví vydávati budete, nebo od počátku se mnou jste."]]}];

JOHN_SECTIONS["16"] = [{"title":"Pronásledování učedníků","range":"Jan 16,1–4","thoughts":[],"verses":[[1,"Toto mluvil jsem vám, abyste se nezhoršili."],[2,"Vypovědíť vás ze škol, ano přijdeť čas, že všeliký, kdož vás mordovati bude, domnívati se bude, že tím Bohu slouží."],[3,"toť učiní vám proto, že nepoznali Otce ani mne."],[4,"Ale toto mluvil jsem vám, abyste, když přijde ten čas, rozpomenuli se na to, že jsem já předpověděl vám. Tohoť pak jsem vám s počátku nemluvil, nebo jsem byl s vámi."]]},{"title":"Působení Ducha svatého","range":"Jan 16,5–15","thoughts":[],"verses":[[5,"Nyní pak jdu k tomu, kterýž mne poslal, a žádný z vás neptá se mne: Kam jdeš?"],[6,"Ale že jsem vám tyto věci mluvil, zámutek naplnil srdce vaše."],[7,"Já pak pravdu říkám vám, že je vám užitečné, abych já odšel. Protože neodejdu-liť, Utěšitel nepřijde k vám; a pakliť odejdu, pošli ho k vám."],[8,"onť přijda, obviňovati bude svět z hříchu, a z spravedlnosti, a z soudu."],[9,"Z hříchu zajisté, že nevěří ve mne."],[10,"z spravedlnosti, proto že jdu k Otci, a již více neuzříte mne."],[11,"Z soudu pak, proto že kníže tohoto světa již je odsouzeno."],[12,"Ještěť bych měl mnoho mluviti vám, ale nemůžete snésti nyní."],[13,"Když pak přijde ten Duch pravdy, uvedeť vás ve všelikou pravdu. Protože nebude mluviti sám od sebe, ale cožkoli uslyší, toť mluviti bude; ano i budoucí věci zvěstovati bude vám."],[14,"Onť mne oslaví; nebo z mého vezme, a zvěstuje vám."],[15,"Všecko, cožkoli má Otec, mé je. Protož jsem řekl, že z mého vezme, a zvěstuje vám."]]},{"title":"Smutek se promění v radost","range":"Jan 16,16–24","thoughts":[],"verses":[[16,"Maličko, a neuzříte mne, a znovu maličko, a uzříte mne; nebo já jdu k Otci."],[17,"řekli někteří z učedníků jeho mezi sebou: Co je to, že praví nám: Maličko, a neuzříte mne, a znovu maličko, a uzříte mne, a že já jdu k Otci?"],[18,"Protož říkali: Co je to, že praví: Maličko? Nevíme, co praví."],[19,"poznal Ježíš, že se ho chtěli otázati. A řekl jim: O tom tížete mezi sebou, že jsem řekl: Maličko, a neuzříte mne, a znovu maličko, a uzříte mne?"],[20,"Amen, amen říkám vám, že plakati a kvíliti budete vy, ale svět se bude radovati; vy pak se budete rmoutiti, ale zámutek váš obrátíť se v radost."],[21,"Žena, když rodí, zámutek má, nebo přišla hodina hoí; ale když porodí děťátko, již nepamatuje na ssoužení, pro radost, proto že se narodil člověk na svět."],[22,"Protož i vy zámutek máte nyní, ale znovu uzřím vás, a radovati se bude srdce vaše, a radosti vaší žádný neodejme od vás."],[23,"v ten den nebudete se mne tázati o ničemž. Amen, amen říkám vám: Že zač byste koli prosili Otce ve jménu mém, dať vám."],[24,"Až dosavad za nic jste neprosili ve jménu mém. Prostež, a vezmete, aby radost vaše doplněna byla."]]},{"title":"Ježíš zvítězil nad světem","range":"Jan 16,25–33","thoughts":[],"verses":[[25,"Toto v příslovích mluvil jsem vám, ale přijdeť hodina, když více nebudu v příslovích mluviti vám, nýbrž zjevně o Otci zvěstovati budu vám."],[26,"V ten den ve jménu mém prositi budete, a nepravímť vám, že já budu prositi Otce za vás."],[27,"Protože sám Otec miluje vás, proto že jste vy mne milovali, a uvěřili, že jsem já od Boha vyšel."],[28,"Vyšelť jsem od Otce, a přišel jsem na svět; a znovu opouštím svět, a jdu k Otci."],[29,"Řkou mu učedlníci jeho: Hle, nyní zjevně mluvíš, a přísloví žádného nepravíš."],[30,"Nyní víme, že víš všechno, a nepotřebuješ, aby se kdo tebe tázal. Skrze to věříme, že jsi od Boha přišel."],[31,"Odpověděl jim Ježíš: Nyní věříte?"],[32,"Hle, přijdeť hodina, anobrž již přišla, že se rozprchnete jeden každý k svému, a mne samého necháte. Ale nejsemť sám, nebo Otec se mnou je."],[33,"Tyto věci mluvil jsem vám, abyste ve mně pokoj měli. Na světě ssoužení míti budete, ale doufejtež, jáť jsem přemohl svět."]]}];

JOHN_SECTIONS["17"] = [{"title":"Ježíš se modlí za sebe","range":"Jan 17,1–5","thoughts":[],"verses":[[1,"To pověděv Ježíš, i pozdvihl oči svých k nebi a řekl: Otče, přišlať hodina, oslaviž Syna svého, aby i Syn tvůj oslavil tebe;"],[2,"Jakož jsi dal mu moc nad každým člověkem, aby těm všechněm, kteréž jsi dal mu, život věčný dal."],[3,"Totoť je pak věčný život, aby poznali tebe samého pravého Boha, a kteréhož jsi poslal, Ježíše Krista."],[4,"Jáť jsem oslavil tebe na zemi; řekllo jsem vykonal, kteréž jsi mi dal, abych činil."],[5,"nyní oslaviž ty mne, Otče, u sebe samého touž slavou, kterouž jsem měl u tebe, prvé nežli svět byl."]]},{"title":"Ježíš se modlí za učedníky","range":"Jan 17,6–19","thoughts":[],"verses":[[6,"Oznámil jsem jméno tvé lidem, kteréž jsi mi dal z světa. Tvojiť byli, a mně jsi je dal, a řeč tvou zachovali."],[7,"nyní poznali, že všecky věci, kteréž jsi mi dal, od tebe jsou."],[8,"Protože slova, kteráž jsi mi dal, dal jsem jim; a oni přijali, a poznali právě, že jsem od tebe vyšel, a uvěřili, že jsi ty mne poslal."],[9,"Já za ně prosím, ne za svět prosím, ale za ty, kteréž jsi mi dal, nebo tvoji jsou."],[10,"všecky věci mé tvé jsou, a tvé mé jsou, a oslaven jsem v nich."],[11,"Již pak více nejsem na světě, ale oni jsou na světě, a já k tobě jdu. Otče svatý, ostříhejž jich ve jménu svém, kteréž jsi mi dal, aťby byli jedno jako my."],[12,"Dokudž jsem s nimi byl na světě, já jsem jich ostříhal ve jménu tvém. Kteréž jsi mi dal, zachoval jsem, a žádný z nich nezahynul, než syn zatracení, aby se písmo naplnilo."],[13,"Ale nyní k tobě jdu, a toto mluvím na světě, aby měli radost mou plnou v sobě."],[14,"Já jsem jim dal slovo tvé, a svět jich nenáviděl; nebo nejsou z světa, jako já nejsem z světa."],[15,"Neprosímť, abys je vzal z světa, ale abys je zachoval od toho zlého."],[16,"Z světať nejsou, jako i já nejsem z světa."],[17,"Posvětiž jich v pravdě své, slovo tvé pravda je."],[18,"Jakož jsi mne poslal na svět, i já jsem je poslal na svět."],[19,"já posvěcuji sebe samého za ně, aby i oni posvěceni byli v pravdě."]]},{"title":"Ježíš se modlí za všechny věřící","range":"Jan 17,20–26","thoughts":[],"verses":[[20,"Ne za tytoť pak toliko prosím, ale i za ty, kteříž skrze slovo jejich mají uvěřiti ve mne,"],[21,"Aby všichni jedno byli, jako ty, Otče, ve mně, a já v tobě, aby i oni v nás jedno byli, aby uvěřil svět, že jsi ty mne poslal."],[22,"já slávu, kterouž jsi mi dal, dal jsem jim, aby byli jedno, jako my jedno jsme."],[23,"Já v nich, a ty ve mně, aby dokonáni byli v jedno, a aby poznal svět, že jsi ty mne poslal, a že jsi je miloval, jakožs mne miloval."],[24,"Otče, kteréž jsi mi dal, chciť, kdež jsem já, aby i oni byli se mnou, aby hleděli na slávu mou, kteroužs mi dal; nebo jsi mne miloval před ustanovením světa."],[25,"Otče spravedlivý, tebeť svět nepoznal, ale já jsem tebe poznal, a i tito poznali, že jsi ty mne poslal."],[26,"známéť jsem jim udělal jméno tvé, a známo udělám, aby milování, kterýmž jsi mne miloval, bylo v nich, a i já v nich."]]}];

JOHN_SECTIONS["18"] = [{"title":"Ježíšovo zatčení","range":"Jan 18,1–11","thoughts":[],"verses":[[1,"To když pověděl Ježíš, vyšel s učedníky svými přes potok Cedron, kdež byla zahrada; do kteréto všel on i učedlníci jeho."],[2,"Věděl pak i Jidáš, zrádce jeho, to místo; nebo často chodíval tam Ježíš s učedníky svými."],[3,"Protož Jidáš pojav zástup, a od předních kněží {biskupů} a farizeů služebníky, přišel tam s lucernami a s pochodněmi a s zbrojí."],[4,"Ježíš pak věda všechno, což přijíti mělo na něj, vyšel, řekl jim: Koho hledáte?"],[5,"Odpověděli mu: Ježíše Nazaretského. Řekl jim Ježíš: Jáť jsem. Stál pak s nimi i Jidáš, zrádce jeho."],[6,"jakž řekl jim: Já jsem, postoupili nazpět, a padli na zem."],[7,"otázal se jich znovu: Koho hledáte? A oni řekli: Ježíše Nazaretského."],[8,"Odpověděl Ježíš: Pověděl jsem vám, že já jsem. Poněvadž tedy mne hledáte, nechtež těchto, ať odejdou."],[9,"Aby se naplnila řeč, kterouž byl pověděl: Z těch, kteréž jsi mi dal, neztratil jsem žádného."],[10,"Šimon Petr, měl meč, vytrhl ho, a udeřil služebníka nejvyššího kněze {biskupova}, a uťal mu ucho jeho pravé. Bylo pak jméno služebníka toho Malchus."],[11,"řekl Ježíš Petrovi: Schovej meč svůj do pošvy. Což nemám píti kalicha, kterýž mi dal Otec?"]]},{"title":"Ježíš před Annášem a Kaifášem","range":"Jan 18,12–24","thoughts":[],"verses":[[12,"zástup a hejtman a služebníci Židovští jali Ježíše, a svázali ho."],[13,"vedli ho k Annášovi nejprvé; nebo byl test Kaifášův, kterýž byl nejvyšším knězem {biskupem} toho léta."],[14,"Kaifáš pak byl ten, kterýž byl radu dal Židům, že by užitečné bylo, aby člověk jeden umřel za lid."],[15,"Šel pak za Ježíšem Šimon Petr a jiný učedník. A ten učedník byl znám nejvyššímu knězi {biskupovi}, i všel s Ježíšem do síně nejvyššího kněze {biskupovy}."],[16,"Ale Petr stál u dveří vně. A vyšel ten druhý učedník, kterýž byl znám nejvyššímu knězi {biskupovi}, a promluvil s vrátnou, i uvedl tam Petra."],[17,"řekla Petrovi děvka vrátná: Nejsi-liž i ty z učedníků člověka toho? Řekl on: Nejsem."],[18,"Stáli pak tu služebníci a pacholci, kteříž oheň udělali, nebo zima bylo, i zhřívali se. A byl s nimi také i Petr, stoje a zhřívaje se."],[19,"nejvyšší kněz {biskup} tázal se Ježíše o učedlnících jeho a o učení jeho."],[20,"Odpověděl mu Ježíš: Já zjevně mluvil jsem světu, já vždycky učíval jsem v škole a v chrámě, kdež se odevšad Židé scházejí, a tajně jsem nic nemluvil."],[21,"Co se mne ptáš? Ptej se těch, kteříž slýchali, co jsem jim mluvil. Hle, tiť vědí, co jsem já mluvil."],[22,"když on to pověděl, jeden z služebníků, stoje tu, dal hůlkou Ježíšovi, řka: Tak-liž odpovídáš nejvyššímu knězi {biskupovi}?"],[23,"Odpověděl mu Ježíš: Mluvil-li jsem zle, svědectví vydej o zlém; pakli dobře, proč mne tepeš?"],[24,"poslal ho Annáš svázaného k Kaifášovi nejvyššímu knězi {biskupovi}."]]},{"title":"Petr zapírá Ježíše","range":"Jan 18,25–27","thoughts":[],"verses":[[25,"Stál pak Šimon Petr, a zhříval se. Potom řekli mu: Nejsi-liž i ty z učedníků jeho? Zapřel on a řekl: Nejsem."],[26,"Dí mu jeden z služebníků nejvyššího kněze {biskupových}, příbuzný toho, kterémuž Petr uťal ucho: Zdaž jsem já tebe neviděl s ním v zahradě?"],[27,"Petr znovu zapřel. A hned kohout zazpíval."]]},{"title":"Ježíš před Pilátem","range":"Jan 18,28–40","thoughts":[],"verses":[[28,"vedli Ježíše od Kaifáše do radného domu, a bylo ráno. Oni pak nevešli do radného domu, aby se nepoškvrnili, ale aby jedli beránka."],[29,"vyšel k nim Pilát a řekl: Jakou žalobu vedete proti člověku tomuto?"],[30,"Odpověděli a řekli mu: Byť tento nebyl zločinec, nevydali bychom ho tobě."],[31,"řekl jim Pilát: Vezměte vy ho, a podlé zákona svého suďte ho. A řekli mu Židé: Námť nesluší zabiti žádného."],[32,"Aby se řeč Ježíšova naplnila, kterouž řekl, znamenaje, kterou by smrtí měl umříti."],[33,"Pilát všel znovu do radného domu, i povolal Ježíše a řekl mu: Ty-li jsi král Židovský?"],[34,"Odpověděl Ježíš: Sám-li od sebe to pravíš, čili jiní tobě pověděli o mně?"],[35,"Odpověděl Pilát: Zdaliž jsem já Žid? Národ tvůj a přední kněží {biskupové} dali mi tebe. Co jsi udělal?"],[36,"Odpověděl Ježíš: Království mé není z tohoto světa. Byť z tohoto světa bylo království mé, služebníci moji bránili by, abych nebyl vydán Židům. Ale nyní mé království není odsud."],[37,"řekl mu Pilát: Potom král jsi ty? Odpověděl Ježíš: Ty pravíš, že já král jsem. Jáť jsem se k tomu narodil, a proto jsem na svět přišel, abych svědectví vydal pravdě. Každý, kdož je z pravdy, slyší hlas můj."],[38,"Dí mu Pilát: Co je pravda? A to pověděv, znovu vyšel k Židům, a dí jim: Já na něm žádné viny nenalézám."],[39,"Ale je obyčej váš, abych vám propustil jednoho na velikunoc. Chcete-liž tedy, ať vám propustím toho krále Židovského?"],[40,"zkřikli znovu všichni, řkouce: Ne toho, ale Barabáše. Byl pak ten Barabáš lotr."]]}];

JOHN_SECTIONS["19"] = [{"title":"Ježíš odsouzen k ukřižování","range":"Jan 19,1–16","thoughts":[],"verses":[[1,"vzal Pilát Ježíše, a zbičoval."],[2,"žoldnéři zpletše korunu z trní, vstavili na hlavu jeho, a pláštěm šarlatovým přioděli ho."],[3,"říkali: Zdráv buď, králi Židovský. A bili ho hůlkami."],[4,"vyšel znovu ven Pilát, a řekl jim: Hle, vyvedu ho vám ven, abyste poznali, žeť na něm žádné viny nenalézám."],[5,"vyšel Ježíš ven, nesa tu korunu trnovou, a ten plášť šarlatový. A řekl jim Pilát: Hle člověk."],[6,"jakž ho uzřeli přední kněží {biskupové} a služebníci, zkřikli, řkouce: Ukřižuj, ukřižuj ho. Dí jim Pilát: Vezměte vy ho a ukřižujte, nebo já na něm viny nenalézám."],[7,"Odpověděli mu Židé: My zákon máme, a podlé zákona našeho máť umříti, nebo Synem Božím se činil."],[8,"když Pilát uslyšel tuto řeč, více se obával."],[9,"všel do radného domu zase, a řekl Ježíšovi: Odkud jsi ty? Ale Ježíš nedal mu odpovědi."],[10,"řekl mu Pilát: Nemluvíš se mnou? Nevíš-liž, že mám moc ukřižovati tě, a moc mám propustiti tebe?"],[11,"Odpověděl Ježíš: Neměl bys nade mnou moci nižádné, byť nebylo dáno s hůry; protož kdo mne tobě vydal, většíť hřích má."],[12,"Od té chvíle hledal Pilát propustiti ho. Ale Židé volali, řkouce: Propustíš-li tohoto, nejsi přítel císařův; každý, kdož se králem činí, protiví se císaři."],[13,"Pilát uslyšev tu řeč, vyvedl ven Ježíše, a sedl na soudné stolici na místě, kteréž slove Litostrotos, a Židovsky Gabbata."],[14,"bylo v pátek před velikonocí, okolo šesté hodiny. A řekl Židům: Hle, král váš."],[15,"Oni pak zkřikli: Vezmi, vezmi, ukřižuj ho. Řekl jim Pilát: Krále vašeho ukřižuji? Odpověděli přední kněží {biskupové}: Nemámeť krále, než císaře."],[16,"Tehdy vydal jim ho, aby byl ukřižován. A pojali Ježíše a vedli."]]},{"title":"Ukřižování","range":"Jan 19,17–27","thoughts":[],"verses":[[17,"nesa kříž svůj, šel na místo, kteréž slove popravné, a Židovsky Golgota."],[18,"Kdež ukřižovali ho, a s ním jiná dva s obou stran, a v prostředku Ježíše."],[19,"Napsal pak i nápis Pilát, a vstavil na kříž. A bylo napsáno: Ježíš Nazaretský, král Židovský."],[20,"Ten pak nápis mnozí z Židů čtli; nebo blízko města bylo to místo, kdež ukřižován byl Ježíš. A bylo psáno Židovsky, Řecky a Latině."],[21,"přední kněží {biskupové} Židovští řekli Pilátovi: Nepiš: Král Židovský, ale že on řekl: Král Židovský jsem."],[22,"Odpověděl Pilát: Co jsem psal, psal jsem."],[23,"Žoldnéři pak, když Ježíše ukřižovali, vzali oděvy jeho, (a učinili čtyři řeklly, každému rytíři řekll), a sukni. Byla pak sukně nesšívaná, ale od vrchu všechna naskrze setkaná."],[24,"řekli mezi sebou: Neroztrhujme jí, ale losujme o ni, čí bude. Aby se naplnilo písmo, řkoucí: Rozdělili sobě oděv mé, a o můj oděv metali los. Potom žoldnéři tak učinili."],[25,"Stály pak u kříže Ježíšova matka jeho a sestra matky jeho, Maria Kleofášova, a Maria Magdaléna."],[26,"Ježíš když uviděl matku, a učedníka tu stojícího, kteréhož miloval, řekl matce své: Ženo, aj, syn tvůj."],[27,"řekl učedníkovi: Hle, matka tvá. A od té hodiny přijal ji učedník ten k sobě."]]},{"title":"Ježíšova smrt","range":"Jan 19,28–37","thoughts":[],"verses":[[28,"věda Ježíš, že již všechno dokonáno je, aby se naplnilo písmo, řekl: Žízním."],[29,"Byla pak tu postavena nádoba plná octa. Potom oni naplnivše hubu octem, a obloživše yzopem, podali ústům jeho."],[30,"když okusil Ježíš octa, řekl: Dokonánoť je. A nakloniv hlavy, ducha Otci poručil."],[31,"Židé pak, aby nezůstala na kříži těla na sobotu, poněvadž byl den připravování, (byl zajisté veliký ten den sobotní), prosili Piláta, aby zlámáni byli hnátové jejich, a byli složeni."],[32,"přišli žoldnéři, a prvnímu zajisté zlámali hnáty, i druhému, kterýž ukřižován byl s ním."],[33,"Ale k Ježíšovi přišelše, jakž uzřeli ho již mrtvého, nelámali hnátů jeho."],[34,"Ale jeden z žoldnéřů bok jeho kopím otevřel, a hned vyšla krev a voda."],[35,"ten, kterýž viděl, svědectví vydal, a pravé je svědectví jeho. Onť ví, že pravé věci praví, abyste vy věřili."],[36,"Stalo se pak to, aby se naplnilo to písmo: Kost jeho nebude zlámána."],[37,"znovu jiné písmo dí: Uzříť, v koho jsou bodli."]]},{"title":"Ježíšův pohřeb","range":"Jan 19,38–42","thoughts":[],"verses":[[38,"pak prosil Piláta Jozef z Arimatie, (kterýž byl učedník Ježíšův, ale tajný, pro strach Židovský), aby sňal tělo Ježíšovo. A dopustil Pilát. A on přišel, sňal tělo Ježíšovo."],[39,"Přišel pak i Nikodém, (kterýž byl prvé přišel k Ježíšovi v noci), nesa smíšení mirry a aloes okolo sta liber."],[40,"vzali tělo Ježíšovo, a obvinuli je prostěradly s těmi vonnými věcmi, jakž obyčej je Židům se pochovávati."],[41,"byla na tom místě, kdež ukřižován byl, zahrada, a v zahradě hrob nový, v němž ještě žádný nebyl pochován."],[42,"Protož tu pro den připravování Židovský, že blízko byl ten hrob, položili Ježíše."]]}];

JOHN_SECTIONS["20"] = [{"title":"Prázdný hrob","range":"Jan 20,1–10","thoughts":[],"verses":[[1,"Prvního pak dne po sobotě Maria Magdaléna šla ráno k hrobu, když ještě tma bylo. A uzřela kámen odvalený od hrobu."],[2,"běžela a přišla k Šimonovi Petrovi a k druhému učedníkovi, tomu, jehož miloval Ježíš, a řekla jim: Vzali Pána z hrobu, a nevíme, kde ho položili."],[3,"vyšel Petr i ten druhý učedník, a šli k hrobu."],[4,"Běželi pak oba spolu. Ale ten druhý učedník předběhl Petra, a přišel prvé k hrobu."],[5,"nachýliv se, uviděl prostěradla položená, ale však tam nevšel."],[6,"přišel Šimon Petr, za ním jda, a všel do hrobu. A uviděl prostěradla položená,"],[7,"rouchu, kteráž byla na hlavě jeho, ne s prostěradly položenou, ale obzvláštně svinutou na jednom místě."],[8,"všel i ten druhý učedník, kterýž byl prvé přišel k hrobu, i uviděl a uvěřil."],[9,"Protože ještě neznali písma, že měl z mrtvých vstáti."],[10,"odešli zase ti učedlníci tam, kdež prvé byli."]]},{"title":"Ježíš se ukazuje Marii Magdaléně","range":"Jan 20,11–18","thoughts":[],"verses":[[11,"Ale Maria stála u hrobu vně, plačeci. A když plakala, naklonila se do hrobu."],[12,"uzřela dva anděly v bílém rouše sedící, jednoho u hlavy, a druhého u noh, tu kdež bylo položeno tělo Ježíšovo."],[13,"Kteříž řekli jí: Ženo, co pláčeš? A dí jim: Vzali Pána mého, a nevím, kde ho položili."],[14,"To když řekla, obrátila se zpátkem, a uzřela Ježíše, an stojí, ale nevěděla, by Ježíš byl."],[15,"Dí jí Ježíš: Ženo, co pláčeš? Koho hledáš? Ona domnívajici se, že by zahradník byl, řekla mu? Pane, vzal-lis ty ho, pověz mi, kdes ho položil, ať já ho vezmu."],[16,"Řekl jí Ježíš: Maria. Obrátivši se ona, řekla mu: Rabbóni, což se vykládá: Mistře."],[17,"Dí jí Ježíš: Nedotýkejž se mne; nebo jsem ještě nevstoupil k Otci svému. Ale jdiž k bratřím mým, a pověz jim: Vstupuji k Otci svému, a k Otci vašemu, k Bohu svému, a k Bohu vašemu."],[18,"Přišla Maria Magdaléna, zvěstujici učedníkům, že by viděla Pána, a že jí to pověděl."]]},{"title":"Ježíš se ukazuje učedníkům","range":"Jan 20,19–23","thoughts":[],"verses":[[19,"Když pak byl večer toho dne, kterýž je první po sobotě, a dvéře byly zavříny, kdež byli učedlníci shromážděni, pro strach Židovský, přišel Ježíš, a stál u prostřed, a řekl jim: Pokoj vám."],[20,"to pověděv, ukázal jim ruce i bok svůj. A zradovali se učedlníci, vidouce Pána."],[21,"řekl jim Ježíš znovu: Pokoj vám. Jakož mne poslal Otec, tak i já posílám vás."],[22,"to pověděv, dechl, a řekl jim: Přijměte Ducha svatého."],[23,"Kterýmžkoli odpustili byste hříchy, odpouštějíť se jim; kterýmžkoli zadrželi byste, zadržániť jsou."]]},{"title":"Tomáš uvěří","range":"Jan 20,24–29","thoughts":[],"verses":[[24,"Tomáš pak jeden ze dvanácti, kterýž sloul Didymus, nebyl s nimi, když byl přišel Ježíš."],[25,"řekli mu jiní učedlníci: Viděli jsme Pána. Ale on řekl jim: Leč uzřím v rukou jeho bodení hřebů, a vpustím prst svůj v místo hřebů, a ruku svou vložím v bok jeho, nikoli neuvěřím."],[26,"po osmi dnech znovu učedlníci jeho byli vnitř, a Tomáš s nimi. Přišel Ježíš, a dvéře byly zavříny, i stál u prostřed a řekl: Pokoj vám."],[27,"řekl Tomášovi: Vložiž prst svůj sem, a viz ruce mé, a vztáhni ruku svou, a vpusť v bok můj, a nebudiž nevěřící, ale věrný."],[28,"odpověděl Tomáš a řekl mu: Pán můj a Bůh můj!"],[29,"Dí mu Ježíš: Žes mne viděl, Tomáši, uvěřil jsi. Blahoslavení, kteříž neviděli, a uvěřili."]]},{"title":"Účel evangelia","range":"Jan 20,30–31","thoughts":[],"verses":[[30,"Mnohé zajisté i jiné divy činil Ježíš před oblíčejem učedníků svých, kteříž nejsou zapsáni v knize této."],[31,"Ale tito zapsáni jsou, abyste věřili, že Ježíš je Kristus, Syn Boží, a abyste věříce, život měli ve jménu jeho."]]}];

JOHN_SECTIONS["21"] = [{"title":"Ježíš se ukazuje u Tiberiadského moře","range":"Jan 21,1–14","thoughts":[],"verses":[[1,"zjevil se znovu Ježíš učedníkům u moře Tiberiadského. Zjevil se pak takto:"],[2,"Byli spolu Šimon Petr a Tomáš, kterýž sloul Didymus, a Natanael, kterýž byl z Kány Galilejské, a synové Zebedeovi, a jiní z učedníků jeho dva."],[3,"Dí jim Šimon Petr: Půjdu ryb loviti. Řekli mu: Půjdeme i my s tebou. A šli, a vstoupili na lodí hned; a té noci nic nepopadli."],[4,"když bylo již ráno, stál Ježíš na břehu. Nevěděli však učedlníci, by Ježíš byl."],[5,"dí jim Ježíš: Dítky, máte-li jakou krmičku? Odpověděli mu: Nemáme."],[6,"On pak řekl jim: Zavrztež sít na pravou stranu lodí, a naleznete. A zavrhli, a hned nemohli ji táhnouti pro množství ryb."],[7,"řekl učedník ten, kteréhož miloval Ježíš, Petrovi: Pán je. A Šimon Petr, jakž uslyšel, že Pán je, opásal se po košili, (nebo byl nah), a pustil se do moře."],[8,"Jiní také učedlníci na lodí připlavili se (nebo nedaleko byli od břehu, asi okolo dvou set loket), táhnouce tu sít s rybami."],[9,"jakž vystoupili na břeh, uzřeli řeřavé uhlí a rybu svrchu položenou a chléb."],[10,"Řekl jim Ježíš: Přineste ryb, kterýchž jste nalapali nyní."],[11,"Vstoupil pak Šimon Petr, a vytáhl sít na zem, plnou ryb velikých, sto padesáte a tři. A ačkoli jich tak mnoho bylo, neztrhala se sít."],[12,"Řekl jim Ježíš: Pojďte, obědujte. Žádný pak z učedníků nesměl se ho otázati: Ty kdo jsi? vědouce, že Pán je."],[13,"přišel Ježíš, a vzal ten chléb, a dával jim, i rybu též."],[14,"To již po třetí ukázal se Ježíš učedníkům svým, vstal z mrtvých."]]},{"title":"Ježíš a Petr","range":"Jan 21,15–19","thoughts":[],"verses":[[15,"když poobědvali, řekl Ježíš Šimonovi Petrovi: Šimone Jonášův, miluješ-li mne více než tito? Řekl mu: Ovšem, Pane, ty víš, že tě miluji. Dí mu: Pasiž beránky mé."],[16,"Řekl mu znovu po druhé: Šimone Jonášův, miluješ-li mne? Řekl mu: Ovšem, Pane, ty víš, že tě miluji. Dí mu: Pasiž ovce mé."],[17,"Řekl mu potřetí: Šimone Jonášův, miluješ-li mne? A zarmoutil se Petr, protože mu řekl potřetí: Miluješ-li mne? A odpověděl mu: Pane, ty znáš všechno, ty víš, že tě miluji. Řekl mu Ježíš: Pasiž ovce mé."],[18,"Amen, amen říkám tobě: Když jsi byl mladší, opasovals se, a chodíval jsi, kams chtěl: ale když se sstaráš, ztáhneš ruce své, a jiný tě opáše, a povede, kamž bys ty nechtěl."],[19,"To pak pověděl, znamenaje, kterou by smrtí měl oslaviti Boha. A to pověděv, řekl mu: Poď za mnou."]]},{"title":"Milovaný učedník","range":"Jan 21,20–25","thoughts":[],"verses":[[20,"obrátiv se Petr, uviděl toho učedníka, kteréhož miloval Ježíš, an jde za ním, kterýž i odpočíval za večeří na prsech jeho, a byl řekl: Pane, kdo je ten, kterýž tě zradí?"],[21,"Toho když viděl Petr, dí Ježíšovi: Pane, co pak tento?"],[22,"Řekl mu Ježíš: Chci-li ho nechati, dokudž nepřijdu, co tobě po tom? Ty poď za mnou."],[23,"vyšla řeč ta mezi bratří, že by učedník ten neměl umříti. Ale neřekl byl mu Ježíš, že by neměl umříti, ale: Chci-li ho nechati, dokudž nepřijdu, co tobě po tom?"],[24,"Toť je učedník ten, kterýž svědectví vydává o těchto věcech, a napsal toto, a víme, že pravé je svědectví jeho."],[25,"Jestiť pak i jiných mnoho věcí, kteréž činil Ježíš, kteréž kdyby měly všecky, každá obzvláštně, psány býti, mám za to, že by ten svět nemohl přijíti těch knih, kteréž by napsány byly. Amen."]]}];

